//! `fe2o3_net::lens`, the generic half of a debug lens.
//!
//! The gates, the envelope and the redaction rule are Daimond's (`gateway/src/handlers/
//! debug_trace.rs` and `www/js/debugshare.js`), so each test here either re-states a Daimond test
//! against the Rust code or pins a value to the JavaScript it mirrors. The two oracle tables in
//! `tests/data` are generated by running `SECRET_RE` and `fingerprint` themselves (see
//! `tests/data/lens_oracle.mjs`), so a transcription error in the Rust cannot hide.

use oxedyne_fe2o3_core::prelude::*;
use oxedyne_fe2o3_jdat::{
    bdat::limits::DecodeLimits,
    prelude::*,
};
use oxedyne_fe2o3_net::{
    guard::floor::KeyFloor,
    lens::{
        chunk,
        compact,
        fingerprint,
        is_stamp,
        judge,
        sanitise,
        secret_name,
        secret_name_loose,
        stamp,
        ChunkTag,
        Deny,
        Gates,
        Or,
        Phrase,
        Posted,
        Redact,
        Refusal,
        Row,
        Shapes,
        Sink,
        StrTest,
        Verdict,
    },
};
use oxedyne_fe2o3_text::{
    base64,
    regex::Regex,
    secret,
};

use std::{
    fs,
    path::{
        Path,
        PathBuf,
    },
    sync::atomic::{
        AtomicU64,
        Ordering,
    },
    time::{
        Duration,
        SystemTime,
        UNIX_EPOCH,
    },
};


// Scratch directories ====================================================================

static SERIAL: AtomicU64 = AtomicU64::new(0);

/// A directory of its own, removed again when the test ends.
struct Scratch(PathBuf);

impl Scratch {
    fn new(tag: &str) -> Self {
        let n = SERIAL.fetch_add(1, Ordering::SeqCst);
        let dir = std::env::temp_dir().join(fmt!("lens-test-{}-{}-{}", std::process::id(), tag, n));
        let _ = fs::remove_dir_all(&dir);
        Self(dir)
    }
    fn dir(&self) -> PathBuf { self.0.join("lens") }
}

impl Drop for Scratch {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}

const T0: u64 = 1_757_635_200_000; // A fixed instant, so rotated names are predictable.
const DAY: u64 = 86_400_000;

// Builders ===============================================================================

fn omap(kv: Vec<(&str, Dat)>) -> Dat {
    create_dat_ordmap(kv.into_iter().map(|(k, v)| (Dat::Str(k.to_string()), v)).collect())
}

fn st(s: &str) -> Dat { Dat::Str(s.to_string()) }

/// The member of a map at a dotted path, lists excluded.
fn at<'a>(d: &'a Dat, path: &str) -> Option<&'a Dat> {
    let mut cur = d;
    for seg in path.split('.') {
        cur = cur.map_get(&st(seg)).ok().flatten()?;
    }
    Some(cur)
}

fn text_of(d: &Dat) -> String {
    match d {
        Dat::Str(s) => s.clone(),
        other       => fmt!("<{:?}>", other),
    }
}

fn text_at(d: &Dat, path: &str) -> String {
    match at(d, path) {
        Some(Dat::Str(s)) => s.clone(),
        other => fmt!("<{:?}>", other),
    }
}

/// A trace body in Daimond's request shape, `{v, device, rows:[{ts, tag, data}]}`.
fn body(device: &str, rows: &[(i64, &str, &str)]) -> Vec<u8> {
    let j = |s: &str| Dat::Str(s.to_string()).json().unwrap_or_default();
    let list: Vec<String> = rows.iter()
        .map(|(ts, tag, data)| fmt!("{{\"ts\":{},\"tag\":{},\"data\":{}}}", ts, j(tag), j(data)))
        .collect();
    fmt!("{{\"v\":1,\"device\":{},\"rows\":[{}]}}", j(device), list.join(",")).into_bytes()
}

fn lines(path: &Path) -> Outcome<Vec<Dat>> {
    let text = res!(fs::read_to_string(path));
    let mut out = Vec::new();
    for line in text.lines() {
        out.push(res!(Dat::decode_json_strict(line, &DecodeLimits::default())));
    }
    Ok(out)
}

fn names(dir: &Path) -> Vec<String> {
    let mut v: Vec<String> = match fs::read_dir(dir) {
        Ok(rd) => rd.filter_map(|e| e.ok()).filter_map(|e| e.file_name().into_string().ok()).collect(),
        Err(_) => Vec::new(),
    };
    v.sort();
    v
}

fn all_bytes(dir: &Path) -> Outcome<Vec<u8>> {
    let mut out = Vec::new();
    for n in names(dir) {
        out.extend(res!(fs::read(dir.join(n))));
    }
    Ok(out)
}

fn has(hay: &[u8], needle: &str) -> bool {
    let n = needle.as_bytes();
    !n.is_empty() && hay.windows(n.len()).any(|w| w == n)
}

fn stored(p: Posted) -> usize {
    match p {
        Posted::Stored(n)   => n,
        Posted::Refused(r)  => panic!("expected the post to be stored, but it was refused: {:?}", r),
    }
}

fn refused(p: Posted) -> Refusal {
    match p {
        Posted::Refused(r)  => r,
        Posted::Stored(n)   => panic!("expected the post to be refused, but {} row(s) were stored", n),
    }
}

/// Pushes a live file past `max_file` so the next write rotates it.
fn overfill(sink: &Sink, key: &[&str]) -> Outcome<()> {
    res!(fs::create_dir_all(sink.dir()));
    res!(fs::write(sink.path(key), vec![b'x'; (sink.gates().max_file + 1) as usize]));
    Ok(())
}

fn small_gates() -> Gates {
    Gates { max_file: 600, ..Gates::default() }
}

fn rotated_name(stem: &str, at_ms: u64) -> String {
    fmt!("{}.ndjson.{}", stem, stamp(at_ms))
}

fn now_real_ms() -> u64 {
    SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_millis() as u64).unwrap_or(0)
}

// The envelope ===========================================================================

#[test]
fn the_row_envelope_is_daimonds_v_d_n_b_t() -> Outcome<()> {
    let row = Row::new("dev1", 7, "b1", T0, "console")
        .with("lvl", st("warn"))
        // The envelope wins over a payload key of the same name, as it does in `emit`.
        .with("n", Dat::U64(99))
        .with("t", Dat::U64(1))
        .with("x", Dat::U64(3));
    let j = res!(row.json());
    assert_eq!(j, fmt!(
        "{{\"v\":1,\"d\":\"dev1\",\"n\":7,\"b\":\"b1\",\"t\":{},\"lvl\":\"warn\",\"x\":3}}", T0));
    assert_eq!(row.tag(), "ev console");
    Ok(())
}

#[test]
fn a_small_row_is_not_trimmed() -> Outcome<()> {
    let row = Row::new("d", 1, "b", T0, "k").with("msg", st("short"));
    let j = res!(row.fit(360));
    assert_eq!(j, res!(row.json()));
    assert!(!j.contains("\"tr\""));
    Ok(())
}

#[test]
fn fit_trims_the_largest_string_and_marks_tr() -> Outcome<()> {
    let row = Row::new("dev1", 7, "b1", T0, "fetch.fail")
        .with("tool", st("bash"))
        .with("err", st(&"e".repeat(1000)));
    let j = res!(row.fit(360));
    assert!(j.len() <= 360, "the fitted event is {} bytes", j.len());
    let d = res!(Dat::decode_json_strict(&j, &DecodeLimits::default()));
    assert_eq!(text_at(&d, "tool"), "bash", "the short field must survive the trimming of the long one");
    let err = text_at(&d, "err");
    assert!(!err.is_empty() && err.len() < 1000 && "e".repeat(err.len()) == err);
    assert!(at(&d, "tr").is_some(), "tr must be present");
    assert!(j.ends_with(",\"tr\":1}"), "tr:1 is the last key: {}", j);
    // The envelope is never sacrificed.
    assert!(j.starts_with(&fmt!("{{\"v\":1,\"d\":\"dev1\",\"n\":7,\"b\":\"b1\",\"t\":{},", T0)));
    Ok(())
}

#[test]
fn fit_counts_bytes_and_still_converges_on_multibyte_text() -> Outcome<()> {
    // 200 characters of two bytes each are trimmed by characters, and the result is whole JSON.
    let row = Row::new("d", 1, "b", T0, "k").with("msg", st(&"é".repeat(200)));
    let j = res!(row.fit(360));
    assert!(j.len() <= 360, "{} bytes", j.len());
    let d = res!(Dat::decode_json_strict(&j, &DecodeLimits::default()));
    let msg = text_at(&d, "msg");
    assert!(!msg.is_empty() && msg.chars().count() < 200 && msg.chars().all(|c| c == 'é'), "{:?}", msg);
    // With 500 the excess in bytes is larger than the characters there are, so the field goes
    // whole, which is what `fit` in debugshare.js does too (`keep > 0` else `delete`).
    let row = Row::new("d", 1, "b", T0, "k").with("msg", st(&"é".repeat(500)));
    let j = res!(row.fit(360));
    assert!(j.len() <= 360, "{} bytes", j.len());
    let d = res!(Dat::decode_json_strict(&j, &DecodeLimits::default()));
    assert!(at(&d, "msg").is_none() && at(&d, "tr").is_some(), "{}", j);
    Ok(())
}

#[test]
fn fit_falls_back_to_the_bare_envelope() -> Outcome<()> {
    // Nothing here is a string, so nothing can be trimmed.
    let big = Dat::List((0..300).map(|i| Dat::U64(1_000_000 + i)).collect());
    let row = Row::new("dev1", 7, "b1", T0, "k").with("big", big);
    let j = res!(row.fit(360));
    assert_eq!(j, fmt!("{{\"v\":1,\"d\":\"dev1\",\"n\":7,\"b\":\"b1\",\"t\":{},\"tr\":1}}", T0));
    Ok(())
}

#[test]
fn an_entry_is_one_ndjson_line_carrying_the_row() -> Outcome<()> {
    let row = Row::new("dev1", 7, "b1", T0, "console").with("msg", st("a\nb\"c\\d"));
    let entry = res!(row.entry(360));
    assert_eq!(entry.ts, T0 as i64);
    assert_eq!(entry.tag, "ev console");
    let line = entry.line("devABC", T0 + 5);
    assert!(line.ends_with('\n'));
    assert_eq!(line.matches('\n').count(), 1, "a row is one line however its text is built");
    let d = res!(Dat::decode_json_strict(line.trim_end(), &DecodeLimits::default()));
    assert_eq!(at(&d, "bt").and_then(|x| x.get_i64()), Some((T0 + 5) as i64));
    assert_eq!(text_at(&d, "device"), "devABC");
    assert_eq!(at(&d, "ts").and_then(|x| x.get_i64()), Some(T0 as i64));
    assert_eq!(text_at(&d, "tag"), "ev console");
    // The data is the event's own JSON, which parses again to the same fields.
    let ev = res!(Dat::decode_json_strict(&text_at(&d, "data"), &DecodeLimits::default()));
    assert_eq!(text_at(&ev, "msg"), "a\nb\"c\\d");
    assert_eq!(text_at(&ev, "d"), "dev1");
    Ok(())
}

// The gates ==============================================================================

#[test]
fn the_gates_carry_daimonds_values_and_the_plans_defaults() {
    let d = Gates::daimond();
    assert_eq!(d.max_body, 256 * 1024);
    assert_eq!(d.max_rows, 1000);
    assert_eq!(d.max_tag, 64);
    assert_eq!(d.max_data, 400);
    assert_eq!(d.min_interval_ms, 2_000);
    assert_eq!(d.max_file, 2 * 1024 * 1024);
    assert_eq!(d.retain_days, 14);
    assert_eq!(d.max_rotated, 200);
    assert_eq!(d.max_total, u64::MAX, "Daimond bounds a device, not the directory");
    assert!(!d.sweep_idle);
    // The plan's defaults (§6): 2 MB files, 7 days or 20 files, 200 MB in all.
    let p = Gates::default();
    assert_eq!((p.max_body, p.max_rows, p.max_tag, p.max_data), (d.max_body, d.max_rows, d.max_tag, d.max_data));
    assert_eq!(p.min_interval_ms, d.min_interval_ms);
    assert_eq!(p.max_file, 2 * 1024 * 1024);
    assert_eq!(p.retain_days, 7);
    assert_eq!(p.max_rotated, 20);
    assert_eq!(p.max_total, 200 * 1024 * 1024);
    assert!(p.sweep_idle);
}

#[test]
fn an_authed_post_appends_a_file_the_operator_can_read() -> Outcome<()> {
    let s = Scratch::new("post");
    let sink = Sink::new(s.dir(), Gates::default());
    let b = body("devABC", &[
        (1000, "dispatch election", "self=aa nominee=bb PRESENT"),
        (1001, "collect CLAIMED", "turn=t1"),
    ]);
    assert_eq!(stored(res!(sink.post(&["acct-diag"], &b, T0))), 2);
    let path = s.dir().join("acct-diag.ndjson");
    assert_eq!(sink.path(&["acct-diag"]), path);
    let got = res!(lines(&path));
    assert_eq!(got.len(), 2);
    assert_eq!(text_at(&got[0], "tag"), "dispatch election");
    assert_eq!(text_at(&got[0], "data"), "self=aa nominee=bb PRESENT");
    assert_eq!(text_at(&got[0], "device"), "devABC");
    assert_eq!(at(&got[0], "bt").and_then(|x| x.get_i64()), Some(T0 as i64));
    assert_eq!(text_at(&got[1], "tag"), "collect CLAIMED");
    Ok(())
}

#[test]
fn a_body_over_the_cap_is_refused_413_and_writes_nothing() -> Outcome<()> {
    let s = Scratch::new("body");
    let sink = Sink::new(s.dir(), Gates::default());
    let mut b = body("d", &[(1, "t", "x")]);
    b.resize(sink.gates().max_body + 1, b' ');
    let r = refused(res!(sink.post(&["k"], &b, T0)));
    assert_eq!(r, Refusal::TooLarge);
    assert_eq!(r.status(), 413);
    assert_eq!(r.message(), "Diagnostic trace too large.");
    assert!(names(&s.dir()).is_empty(), "a refused body must not create a file");
    Ok(())
}

#[test]
fn a_body_exactly_at_the_cap_is_not_refused_for_size() -> Outcome<()> {
    let s = Scratch::new("bodyat");
    let sink = Sink::new(s.dir(), Gates::default());
    let mut b = body("d", &[(1, "t", "x")]);
    b.resize(sink.gates().max_body, b' ');
    assert_eq!(stored(res!(sink.post(&["k"], &b, T0))), 1);
    Ok(())
}

#[test]
fn more_rows_than_the_cap_are_refused_not_truncated() -> Outcome<()> {
    let s = Scratch::new("rows");
    let sink = Sink::new(s.dir(), Gates::default());
    let many: Vec<(i64, &str, &str)> = (0..1001).map(|i| (i as i64, "t", "x")).collect();
    let r = refused(res!(sink.post(&["k"], &body("d", &many), T0)));
    assert_eq!(r, Refusal::TooManyRows);
    assert_eq!(r.status(), 400);
    assert_eq!(r.message(), "Too many rows in one trace.");
    assert!(names(&s.dir()).is_empty(), "a disagreement is loud: nothing is written");
    // Exactly the cap is accepted, whole.
    assert_eq!(stored(res!(sink.post(&["k"], &body("d", &many[..1000]), T0))), 1000);
    assert_eq!(res!(lines(&sink.path(&["k"]))).len(), 1000);
    Ok(())
}

#[test]
fn a_body_with_no_rows_list_or_no_json_is_refused_400() -> Outcome<()> {
    let s = Scratch::new("shape");
    let sink = Sink::new(s.dir(), Gates::default());
    let r = refused(res!(sink.post(&["k"], br#"{"v":1,"device":"d"}"#, T0)));
    assert_eq!(r, Refusal::NoRows);
    assert_eq!(r.status(), 400);
    assert_eq!(r.message(), "A trace must carry a `rows` list.");
    let r = refused(res!(sink.post(&["k"], b"not json at all", T0 + 10_000)));
    assert!(matches!(r, Refusal::Malformed(_)));
    assert_eq!(r.status(), 400);
    let r = refused(res!(sink.post(&["k"], b"", T0 + 20_000)));
    assert!(matches!(r, Refusal::Malformed(_)));
    assert!(names(&s.dir()).is_empty());
    Ok(())
}

#[test]
fn a_tag_and_a_data_field_are_clipped_on_a_character_boundary() -> Outcome<()> {
    let s = Scratch::new("clip");
    let sink = Sink::new(s.dir(), Gates::default());
    let long_tag = "t".repeat(100);
    let long_data = "d".repeat(500);
    let wide = "é".repeat(300); // 600 bytes
    let b = body("d", &[(1, &long_tag, &long_data), (2, "wide", &wide)]);
    assert_eq!(stored(res!(sink.post(&["k"], &b, T0))), 2);
    let got = res!(lines(&sink.path(&["k"])));
    assert_eq!(text_at(&got[0], "tag").len(), 64);
    assert_eq!(text_at(&got[0], "data").len(), 400);
    let w = text_at(&got[1], "data");
    assert!(w.len() <= 400 && w.len() >= 398, "{} bytes", w.len());
    assert!(w.chars().all(|c| c == 'é'), "the clip must not cut a character");
    Ok(())
}

#[test]
fn a_row_cannot_forge_another_by_carrying_a_line_break() -> Outcome<()> {
    let s = Scratch::new("forge");
    let sink = Sink::new(s.dir(), Gates::default());
    let b = body("d", &[(1, "tag", "line1\n{\"forged\":1}\r\n\tend")]);
    assert_eq!(stored(res!(sink.post(&["k"], &b, T0))), 1);
    let text = res!(fs::read_to_string(sink.path(&["k"])));
    assert_eq!(text.matches('\n').count(), 1, "one row, one line: {:?}", text);
    let got = res!(lines(&sink.path(&["k"])));
    assert_eq!(text_at(&got[0], "data"), "line1 {\"forged\":1}   end");
    Ok(())
}

#[test]
fn a_row_with_no_tag_is_marked_not_dropped() -> Outcome<()> {
    let s = Scratch::new("malformed");
    let sink = Sink::new(s.dir(), Gates::default());
    let b = br#"{"v":1,"device":"d","rows":[{"ts":1},{"ts":2,"tag":"ok","data":"x"}]}"#;
    assert_eq!(stored(res!(sink.post(&["k"], b, T0))), 2);
    let got = res!(lines(&sink.path(&["k"])));
    assert_eq!(got.len(), 2);
    assert_eq!(text_at(&got[0], "tag"), "(malformed row)");
    assert_eq!(text_at(&got[1], "tag"), "ok");
    Ok(())
}

// The rate floor =========================================================================

#[test]
fn the_rate_floor_refuses_under_two_seconds_and_accepts_over() -> Outcome<()> {
    let s = Scratch::new("rate");
    let sink = Sink::new(s.dir(), Gates::default());
    let b = body("devR", &[(1, "pull", "x")]);
    assert_eq!(stored(res!(sink.post(&["acct-rate"], &b, T0))), 1);
    let r = refused(res!(sink.post(&["acct-rate"], &b, T0 + 1_500)));
    assert_eq!(r, Refusal::TooFast);
    assert_eq!(r.status(), 429);
    assert_eq!(r.message(), "Wait a moment before sharing again.");
    // The refusal did not hold the floor open: 2.5 s after the first is 1 s after the refusal.
    assert_eq!(stored(res!(sink.post(&["acct-rate"], &b, T0 + 2_500))), 1);
    // Exactly the interval is enough, as `now - last < MIN_INTERVAL_MS` is the refusal.
    assert_eq!(stored(res!(sink.post(&["acct-rate"], &b, T0 + 4_500))), 1);
    // Another key is another floor.
    assert_eq!(stored(res!(sink.post(&["acct-other"], &b, T0 + 4_600))), 1);
    assert_eq!(res!(lines(&sink.path(&["acct-rate"]))).len(), 3);
    Ok(())
}

#[test]
fn the_floor_is_keyed_by_the_session_key_never_by_the_body() -> Outcome<()> {
    let s = Scratch::new("bodykey");
    let sink = Sink::new(s.dir(), Gates::default());
    assert_eq!(stored(res!(sink.post(&["acct"], &body("devX", &[(1, "a", "x")]), T0))), 1);
    // The same session claiming another device in the body is still the same floor.
    let r = refused(res!(sink.post(&["acct"], &body("devY", &[(1, "a", "x")]), T0 + 100)));
    assert_eq!(r, Refusal::TooFast);
    // The body's device is a label on the line, and names no file.
    assert_eq!(names(&s.dir()), vec!["acct.ndjson".to_string()]);
    // A hostile label cannot walk out of the directory, or split a line.
    let h = body("../../etc/passwd\nx", &[(1, "a", "x")]);
    assert_eq!(stored(res!(sink.post(&["acct2"], &h, T0))), 1);
    assert_eq!(names(&s.dir()), vec!["acct.ndjson".to_string(), "acct2.ndjson".to_string()]);
    assert_eq!(res!(lines(&sink.path(&["acct2"]))).len(), 1);
    Ok(())
}

#[test]
fn the_key_floor_remembers_the_last_admitted_call_only() -> Outcome<()> {
    let f = KeyFloor::new(2_000);
    assert!(res!(f.admit("a", 10_000)));
    assert!(!res!(f.admit("a", 11_999)));
    assert!(!res!(f.admit("a", 11_999)), "a refusal leaves the record alone");
    assert!(res!(f.admit("a", 12_000)), "the interval itself is enough");
    assert!(res!(f.admit("b", 12_001)), "keys are independent");
    // A clock that steps back never underflows into a long refusal.
    assert!(!res!(f.admit("b", 1)));
    Ok(())
}

#[test]
fn the_key_floor_prunes_stale_keys_only_once_it_has_grown() -> Outcome<()> {
    let f = KeyFloor::new(2_000).with_ttl_ms(10_000).with_prune_at(3);
    for (i, k) in ["a", "b", "c"].iter().enumerate() {
        assert!(res!(f.admit(k, 1_000 + i as u64)));
    }
    // Three entries, at the bound, not past it: nothing is walked.
    assert!(res!(f.admit("d", 20_000)));
    // Now past the bound, and a, b, c are older than the time to live.
    assert!(res!(f.admit("e", 20_001)));
    assert_eq!(res!(f.len()), 2, "only d and e are younger than the time to live");
    Ok(())
}

// Hostile keys ===========================================================================

#[test]
fn a_key_is_reduced_to_a_safe_filename_alphabet() {
    assert_eq!(sanitise("acct_AB-12"), "acct_AB-12");
    assert_eq!(sanitise("../../etc/passwd"), "______etc_passwd");
    assert!(!sanitise("../../etc/passwd").contains('/'));
    assert_eq!(sanitise(""), "unknown");
    assert!(sanitise(&"x".repeat(100)).len() <= 48);
}

#[test]
fn a_hostile_key_cannot_escape_the_directory() -> Outcome<()> {
    let s = Scratch::new("escape");
    let sink = Sink::new(s.dir(), Gates::default());
    let p = sink.path(&["../../etc", "passwd"]);
    assert_eq!(p, s.dir().join("______etc-passwd.ndjson"));
    assert_eq!(stored(res!(sink.post(&["../../etc", "passwd"], &body("d", &[(1, "t", "x")]), T0))), 1);
    assert_eq!(names(&s.dir()), vec!["______etc-passwd.ndjson".to_string()]);
    // Daimond's key is account and device, each reduced on its own and joined by a hyphen.
    assert_eq!(sink.path(&["acct-diag", "devABC"]), s.dir().join("acct-diag-devABC.ndjson"));
    Ok(())
}

// Rotation ===============================================================================

#[test]
fn a_stamp_is_fixed_width_utc_and_sorts_as_a_string() {
    assert_eq!(stamp(0),          "19700101T000000Z");
    assert_eq!(stamp(86_399_000), "19700101T235959Z");
    assert_eq!(stamp(T0),         "20250912T000000Z");
    assert!(is_stamp(&stamp(T0)));
    assert!(!is_stamp("1"), "a pre-stamp `.log.1` suffix is not a stamp");
    assert!(!is_stamp("1970010 T000000Z"));
    assert!(stamp(0) < stamp(86_399_000));
}

#[test]
fn rotation_by_size_stamps_the_closed_file_and_starts_fresh() -> Outcome<()> {
    let s = Scratch::new("size");
    let sink = Sink::new(s.dir(), small_gates());
    let live = sink.path(&["acct"]);
    res!(fs::create_dir_all(s.dir()));
    // A file of exactly the cap is not past it.
    res!(fs::write(&live, vec![b'x'; 600]));
    assert_eq!(stored(res!(sink.post(&["acct"], &body("d", &[(1, "first", "a")]), T0))), 1);
    assert_eq!(names(&s.dir()), vec!["acct.ndjson".to_string()], "600 bytes is not over a cap of 600");
    // Now it is past the cap, so the next append closes it under the instant of the rotation.
    let rot_ms = T0 + 6_000;
    assert_eq!(stored(res!(sink.post(&["acct"], &body("d", &[(2, "after-rotate", "b")]), rot_ms))), 1);
    let rotated = s.dir().join(rotated_name("acct", rot_ms));
    assert!(rotated.exists(), "the oversized file should have rotated to a stamped name: {:?}", names(&s.dir()));
    let old = res!(fs::read_to_string(&rotated));
    assert!(old.contains("first"), "the rotated file must keep the history, not discard it");
    let fresh = res!(fs::read_to_string(&live));
    assert!(fresh.contains("after-rotate"));
    assert!(!fresh.contains("first"), "the fresh file must not hold pre-rotation content");
    Ok(())
}

#[test]
fn two_rotations_in_one_second_do_not_overwrite_each_other() -> Outcome<()> {
    let s = Scratch::new("collide");
    let sink = Sink::new(s.dir(), small_gates());
    let row = Row::new("d", 1, "b", T0, "k").with("m", st("x"));
    res!(sink.write(&["acct"], "dev", &[row.clone()], T0));
    res!(overfill(&sink, &["acct"]));
    res!(sink.write(&["acct"], "dev", &[row.clone()], T0 + 1_000));
    res!(overfill(&sink, &["acct"]));
    res!(sink.write(&["acct"], "dev", &[row.clone()], T0 + 1_000));
    let n = names(&s.dir());
    let first = rotated_name("acct", T0 + 1_000);
    assert!(n.contains(&first), "{:?}", n);
    assert!(n.contains(&fmt!("{}-1", first)), "an occupied stamp takes a -1 suffix: {:?}", n);
    Ok(())
}

#[test]
fn rotation_by_age_drops_the_over_age_files_and_leaves_the_rest() -> Outcome<()> {
    let s = Scratch::new("age");
    let sink = Sink::new(s.dir(), small_gates());
    let now = 40 * DAY;
    res!(fs::create_dir_all(s.dir()));
    let over_age = rotated_name("acct", now - 8 * DAY);   // Past the plan's 7 days.
    let in_age   = rotated_name("acct", now - 6 * DAY);
    let other    = rotated_name("other", now - 20 * DAY); // Past the age, and another key's.
    let other_in = rotated_name("other", now - 2 * DAY);
    for n in [&over_age, &in_age, &other, &other_in, &"acct.ndjson.1".to_string()] {
        res!(fs::write(s.dir().join(n), b"rotated\n"));
    }
    res!(overfill(&sink, &["acct"]));
    res!(sink.write(&["acct"], "dev", &[Row::new("d", 1, "b", now, "k")], now));
    let n = names(&s.dir());
    assert!(!n.contains(&over_age), "a rotation past retain_days should be gone: {:?}", n);
    assert!(n.contains(&in_age));
    // The sweep covers the directory, where Daimond's prune covered one device's files, because
    // a directory keyed by session grows a key at a time and the others never rotate again.
    assert!(!n.contains(&other), "another key's file past the age goes too: {:?}", n);
    assert!(n.contains(&other_in), "and one inside it stays");
    assert!(n.contains(&"acct.ndjson.1".to_string()), "a pre-stamp rotation is left alone");
    assert!(n.contains(&rotated_name("acct", now)), "the rotation that triggered the prune is kept");
    // Daimond's own age is 14 days, which keeps the 8-day-old file.
    let s2 = Scratch::new("age14");
    let sink2 = Sink::new(s2.dir(), Gates { max_file: 600, ..Gates::daimond() });
    res!(fs::create_dir_all(s2.dir()));
    res!(fs::write(s2.dir().join(&over_age), b"rotated\n"));
    res!(fs::write(s2.dir().join(rotated_name("acct", now - 15 * DAY)), b"rotated\n"));
    res!(overfill(&sink2, &["acct"]));
    res!(sink2.write(&["acct"], "dev", &[Row::new("d", 1, "b", now, "k")], now));
    let n2 = names(&s2.dir());
    assert!(n2.contains(&over_age), "an 8-day-old file is inside Daimond's 14 days: {:?}", n2);
    assert!(!n2.contains(&rotated_name("acct", now - 15 * DAY)));
    Ok(())
}

#[test]
fn rotation_by_count_keeps_the_newest_max_rotated() -> Outcome<()> {
    let s = Scratch::new("count");
    let sink = Sink::new(s.dir(), Gates { max_file: 600, max_rotated: 5, ..Gates::default() });
    let now = 40 * DAY;
    res!(fs::create_dir_all(s.dir()));
    // Seven rotations inside the age, a minute apart, newest first in `in_age`.
    let mut in_age = Vec::new();
    for k in 1..=7u64 {
        let n = rotated_name("acct", now - k * 60_000);
        res!(fs::write(s.dir().join(&n), b"rotated\n"));
        in_age.push(n);
    }
    res!(overfill(&sink, &["acct"]));
    res!(sink.write(&["acct"], "dev", &[Row::new("d", 1, "b", now, "k")], now));
    let n = names(&s.dir());
    // Eight rotations now stand (the seven and the one just made); five are kept, newest first.
    assert!(n.contains(&rotated_name("acct", now)));
    for kept in &in_age[..4] {
        assert!(n.contains(kept), "{} should survive: {:?}", kept, n);
    }
    for gone in &in_age[4..] {
        assert!(!n.contains(gone), "{} is over the count and should be gone: {:?}", gone, n);
    }
    assert!(n.contains(&"acct.ndjson".to_string()), "the live file is not a rotation");
    Ok(())
}

#[test]
fn the_total_cap_deletes_the_oldest_rotations_across_keys() -> Outcome<()> {
    let s = Scratch::new("total");
    let sink = Sink::new(s.dir(), Gates {
        max_file:   200,
        max_total:  3_000,
        max_rotated: 100,
        ..Gates::default()
    });
    let now = 40 * DAY;
    res!(fs::create_dir_all(s.dir()));
    let kb = vec![b'r'; 1_000];
    let order = [("a", 6), ("b", 5), ("a", 4), ("b", 3), ("a", 2)]; // Oldest first, in days back.
    let mut made = Vec::new();
    for (stem, back) in order {
        let n = rotated_name(stem, now - back * DAY / 2);
        res!(fs::write(s.dir().join(&n), &kb));
        made.push(n);
    }
    res!(overfill(&sink, &["c"]));
    res!(sink.write(&["c"], "dev", &[Row::new("d", 1, "b", now, "k")], now));
    let n = names(&s.dir());
    for gone in &made[..3] {
        assert!(!n.contains(gone), "{} is among the oldest and should be gone: {:?}", gone, n);
    }
    for kept in &made[3..] {
        assert!(n.contains(kept), "{} should survive: {:?}", kept, n);
    }
    assert!(n.contains(&rotated_name("c", now)));
    assert!(n.contains(&"c.ndjson".to_string()), "the file being written is never swept");
    let total: u64 = n.iter().map(|f| fs::metadata(s.dir().join(f)).map(|m| m.len()).unwrap_or(0)).sum();
    assert!(total <= 3_000, "{} bytes remain", total);
    Ok(())
}

#[test]
fn idle_live_files_age_out_when_the_gates_say_so() -> Outcome<()> {
    let now = now_real_ms();
    let make = |gates: Gates, tag: &str| -> Outcome<(Scratch, Sink)> {
        let s = Scratch::new(tag);
        let sink = Sink::new(s.dir(), gates);
        res!(fs::create_dir_all(s.dir()));
        for (name, back) in [("old.ndjson", 8 * DAY), ("fresh.ndjson", 3_600_000)] {
            let f = res!(fs::File::create(s.dir().join(name)));
            res!(f.set_modified(UNIX_EPOCH + Duration::from_millis(now - back)));
        }
        Ok((s, sink))
    };
    // A first row for a new key is what sets the sweep off.
    let (s, sink) = res!(make(Gates::default(), "idle"));
    assert_eq!(stored(res!(sink.post(&["new"], &body("d", &[(1, "t", "x")]), now))), 1);
    assert_eq!(names(&s.dir()), vec!["fresh.ndjson".to_string(), "new.ndjson".to_string()],
        "an idle file past retain_days goes, a recent one and the new one stay");
    // Daimond never swept a device that had gone quiet.
    let (s, sink) = res!(make(Gates::daimond(), "idle-daimond"));
    assert_eq!(stored(res!(sink.post(&["new"], &body("d", &[(1, "t", "x")]), now))), 1);
    assert_eq!(names(&s.dir()).len(), 3, "{:?}", names(&s.dir()));
    Ok(())
}

#[cfg(unix)]
#[test]
fn the_directory_is_created_0700_and_the_files_0600() -> Outcome<()> {
    use std::os::unix::fs::PermissionsExt;
    let s = Scratch::new("perm");
    let sink = Sink::new(s.dir(), Gates::default());
    assert_eq!(stored(res!(sink.post(&["k"], &body("d", &[(1, "t", "x")]), T0))), 1);
    let mode = |p: &Path| fs::metadata(p).map(|m| m.permissions().mode() & 0o777).unwrap_or(0);
    assert_eq!(mode(&s.dir()), 0o700);
    assert_eq!(mode(&sink.path(&["k"])), 0o600);
    // A directory that already exists, and is open to others, is closed.
    let s2 = Scratch::new("perm2");
    res!(fs::create_dir_all(s2.dir()));
    res!(fs::set_permissions(s2.dir(), fs::Permissions::from_mode(0o755)));
    let sink2 = Sink::new(s2.dir(), Gates::default());
    assert_eq!(stored(res!(sink2.post(&["k"], &body("d", &[(1, "t", "x")]), T0))), 1);
    assert_eq!(mode(&s2.dir()), 0o700);
    Ok(())
}

