#[test]
fn secret_name_is_secret_re_over_three_thousand_names() -> Outcome<()> {
    let table = res!(fs::read_to_string(
        Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/lens_secret_re.tsv")));
    let mut n = 0;
    let mut hits = 0;
    for line in table.lines() {
        let cols: Vec<&str> = line.split('\t').collect();
        assert_eq!(cols.len(), 3, "bad oracle line {:?}", line);
        let (name, strict, loose) = (cols[0], cols[1] == "1", cols[2] == "1");
        assert_eq!(secret_name(name), strict, "SECRET_RE on {:?}", name);
        assert_eq!(secret_name_loose(name), loose, "SECRET_RE or SECRET_RE_LOOSE on {:?}", name);
        n += 1;
        if strict { hits += 1; }
    }
    assert!(n > 3_000, "the oracle holds {} names", n);
    assert!(hits > 500 && hits < n, "a table that is all one answer proves nothing: {} of {}", hits, n);
    Ok(())
}

#[test]
fn a_fingerprint_is_what_the_javascript_makes() -> Outcome<()> {
    let table = res!(fs::read_to_string(
        Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/lens_fingerprint.tsv")));
    let red = Redact::new();
    let mut n = 0;
    for line in table.lines() {
        let (input, want) = match line.split_once('\t') {
            Some(p) => p,
            None => panic!("bad oracle line {:?}", line),
        };
        let want = text_of(&res!(Dat::decode_json_strict(want, &DecodeLimits::default())));
        let want = want.as_str();
        // Each input is JSON, so null and a number take the route a field value takes.
        let v = res!(Dat::decode_json_strict(input, &DecodeLimits::default()));
        let out = red.dat(&omap(vec![("secret", v.clone())]));
        assert_eq!(text_at(&out, "secret"), want, "fingerprint of {}", input);
        if let Dat::Str(s) = &v {
            assert_eq!(fingerprint(s, 6), want, "fingerprint() of {}", input);
        }
        n += 1;
    }
    assert!(n >= 20);
    Ok(())
}

#[test]
fn the_head_of_a_fingerprint_can_be_withheld() {
    let fp = fingerprint("hunter2hunter2", 0);
    assert!(fp.starts_with("[redacted …#") && fp.ends_with("/14]"), "{}", fp);
    assert!(!fp.contains("hunter"));
    assert_eq!(fingerprint("", 0), "[redacted:empty]");
    // The same hash whatever the head, so two occurrences of one secret still match.
    let a = fingerprint("hunter2hunter2", 6);
    assert_eq!(a.split('#').nth(1), fp.split('#').nth(1));
    // And a redactor can be set to withhold it everywhere.
    let r = Redact::new().with_head(0).dat(&omap(vec![("password", st("hunter2hunter2"))]));
    assert_eq!(text_at(&r, "password"), fp);
}

