#[test]
fn secret_named_fields_are_fingerprinted_at_any_depth() -> Outcome<()> {
    let d = omap(vec![
        ("a", omap(vec![("b", Dat::List(vec![
            omap(vec![("password", st("p1")), ("ok", st("fine"))]),
            st("a bare string in a list is not a field"),
        ]))])),
        ("token", omap(vec![("x", Dat::U64(1))])),    // A secret-named object is noted, not walked.
        ("key", Dat::List(vec![Dat::U64(1), Dat::U64(2)])),
        ("salt", Dat::U64(77)),
        ("n", Dat::U64(5)),
        ("apiKey", st("sk-live-abcdef")),
        ("gone", Dat::Opt(Box::new(None))),
        ("seed", Dat::Opt(Box::new(None))),
    ]);
    let r = Redact::new().dat(&d);
    assert_eq!(text_at(&r, "token"), "[redacted:object]");
    assert_eq!(text_at(&r, "key"), "[redacted:object]");
    assert_eq!(text_at(&r, "salt"), fingerprint("77", 6));
    assert_eq!(text_at(&r, "apiKey"), fingerprint("sk-live-abcdef", 6));
    assert_eq!(text_at(&r, "seed"), "[redacted:absent]");
    assert_eq!(at(&r, "n"), Some(&Dat::U64(5)));
    assert_eq!(at(&r, "gone"), Some(&Dat::Opt(Box::new(None))), "an empty field not named secret is left alone");
    let j = res!(compact(&r));
    assert!(!j.contains("\"p1\"") && !j.contains("sk-live-abcdef"), "{}", j);
    assert!(j.contains("\"ok\":\"fine\"") && j.contains("a bare string in a list"), "{}", j);
    Ok(())
}

#[test]
fn a_camel_cased_name_needs_the_loose_companion() -> Outcome<()> {
    let d = omap(vec![("pushToken", st("t0k3n-value")), ("tokenStats", Dat::U64(3)), ("note", st("n"))]);
    let strict = Redact::new().dat(&d);
    assert_eq!(text_at(&strict, "pushToken"), "t0k3n-value", "SECRET_RE misses a camel-joined name");
    let loose = Redact::new().loose().dat(&d);
    assert_eq!(text_at(&loose, "pushToken"), fingerprint("t0k3n-value", 6));
    assert_eq!(text_at(&loose, "tokenStats"), fingerprint("3", 6), "the loose pattern is boundary-free");
    assert_eq!(text_at(&loose, "note"), "n");
    Ok(())
}

#[test]
fn deny_names_and_paths_are_redacted_and_anchored_paths_stay_anchored() -> Outcome<()> {
    let red = Redact::new()
        .deny_name("durable")
        .deny(Deny::Path(vec!["state".to_string(), "wallet".to_string(), "coins".to_string()]))
        .deny_path(&["sess", "*", "nonce"]);
    let d = omap(vec![
        ("x", omap(vec![("durable", st("D1")), ("fine", st("F"))])),
        ("state", omap(vec![("wallet", omap(vec![("coins", st("C1")), ("name", st("w"))]))])),
        ("other", omap(vec![("state", omap(vec![("wallet", omap(vec![("coins", st("C2"))]))]))])),
        // A list is transparent to a path, so the elements are the object's own members.
        ("sess", Dat::List(vec![omap(vec![("a", omap(vec![("nonce", st("N1"))]))])])),
    ]);
    let r = red.dat(&d);
    assert_eq!(text_at(&r, "x.durable"), fingerprint("D1", 6));
    assert_eq!(text_at(&r, "x.fine"), "F");
    assert_eq!(text_at(&r, "state.wallet.coins"), fingerprint("C1", 6));
    assert_eq!(text_at(&r, "state.wallet.name"), "w");
    assert_eq!(text_at(&r, "other.state.wallet.coins"), "C2", "a path from the root does not match deeper down");
    let j = res!(compact(&r));
    assert!(j.contains(&fingerprint("N1", 6)) && !j.contains("\"N1\""), "{}", j);
    Ok(())
}

#[test]
fn a_caller_string_test_redacts_values_keys_and_list_members() -> Outcome<()> {
    let eight = "alpha bravo charlie delta echo foxtrot golf hotel";
    let seven = "alpha bravo charlie delta echo foxtrot golf";
    let red = Redact::new().with_test(|s: &str| s.split(' ').count() == 8);
    let d = omap(vec![
        ("msg", st(&fmt!("{} done", "boot"))),
        ("phrase", st(eight)),
        ("near", st(seven)),
        ("list", Dat::List(vec![st("x"), st(eight)])),
        ("nest", omap(vec![("deep", st(eight))])),
        (eight, st("a value under a key that is itself the phrase")),
    ]);
    let r = red.dat(&d);
    assert_eq!(text_at(&r, "phrase"), fingerprint(eight, 6));
    assert_eq!(text_at(&r, "near"), seven, "seven words are not the pattern");
    assert_eq!(text_at(&r, "msg"), "boot done");
    assert_eq!(text_at(&r, "nest.deep"), fingerprint(eight, 6));
    let j = res!(compact(&r));
    assert!(!j.contains(eight), "the phrase survives somewhere: {}", j);
    assert!(j.contains(&fingerprint(eight, 6)));
    Ok(())
}

#[test]
fn the_walk_is_bounded_and_a_marker_stands_where_it_stops() -> Outcome<()> {
    let mut d = omap(vec![("leaf", st("DEEP-PLANT"))]);
    for _ in 0..45 {
        d = omap(vec![("n", d)]);
    }
    let r = Redact::new().dat(&d);
    let j = res!(compact(&r));
    assert!(j.contains("[redacted:cycle-or-deep]"), "{}", j);
    assert!(!j.contains("DEEP-PLANT"));
    Ok(())
}

#[test]
fn redacting_twice_does_not_fingerprint_a_fingerprint() -> Outcome<()> {
    let d = omap(vec![("passphrase", st("correct horse")), ("n", Dat::U64(1))]);
    let red = Redact::new();
    let once = red.dat(&d);
    let (twice, changed) = red.walk(&once);
    assert_eq!(res!(compact(&once)), res!(compact(&twice)));
    assert!(!changed, "a marker already in place is not a change");
    let (_, changed) = red.walk(&d);
    assert!(changed);
    let (_, changed) = red.walk(&omap(vec![("ok", st("fine"))]));
    assert!(!changed);
    Ok(())
}

// Nothing planted reaches a byte =========================================================

const PHRASE: &str = "abandon ability able about above absent absorb abstract";

/// Does the text hold eight lowercase words in a row? Oxegen's own test asks the same of the EFF list.
fn eight_words(s: &str) -> bool {
    let w: Vec<bool> = s.split(' ')
        .map(|x| !x.is_empty() && x.chars().all(|c| c.is_ascii_lowercase()))
        .collect();
    w.windows(8).any(|win| win.iter().all(|&b| b))
}

#[test]
fn a_planted_secret_is_absent_from_every_byte_written() -> Outcome<()> {
    let plants = [
        "PLANT-passphrase-1", "PLANT-wallet-seedling-2", "PLANT-durable-3", "PLANT-token-4",
        "PLANT-apikey-5", "PLANT-listmember-6",
    ];
    let s = Scratch::new("planted");
    let sink = Sink::new(s.dir(), Gates { max_file: 900, ..Gates::default() })
        .with_redact(Redact::new()
            .deny_name("durable_blob")
            .deny_path(&["state", "wallet", "seedling"])
            .with_test(eight_words));
    let dev = "peer";
    // The typed door: rows built in process, as the peer's own taps will.
    for i in 0..12u64 {
        let row = Row::new(dev, i, "b1", T0 + i, "state")
            .with("auth", omap(vec![("passphrase", st(plants[0])), ("user", st("ann"))]))
            .with("state", omap(vec![("wallet", omap(vec![("seedling", st(plants[1])), ("open", Dat::Bool(true))]))]))
            .with("durable_blob", st(plants[2]))
            .with("console", st(&fmt!("boot {} done", PHRASE)))
            .with("list", Dat::List(vec![st("x"), st(PHRASE)]))
            .with("tokenStats", Dat::U64(5));
        assert_eq!(res!(sink.write(&["sid-1"], dev, &[row], T0 + 1_000 * i)), 1);
    }
    // The posted door: a client's batch, whose events are JSON inside a string.
    let ev = fmt!(
        "{{\"v\":1,\"d\":\"dev1\",\"n\":1,\"b\":\"b\",\"t\":1,\"token\":\"{}\",\"nested\":{{\"api_key\":\"{}\",\"list\":[\"{}\"],\"keep\":\"kept\"}}}}",
        plants[3], plants[4], PHRASE);
    let text_row = fmt!("saw {} in a plain text row", PHRASE);
    for i in 0..6i64 {
        let b = body("devX", &[(i, "ev console", &ev), (i, "diag", &text_row)]);
        assert_eq!(stored(res!(sink.post(&["sid-2"], &b, T0 + 3_000 * i as u64))), 2);
    }
    // An event whose data is no JSON cannot be examined by name, so it is not kept.
    let broken = fmt!("{{\"token\":\"{}\" oops", plants[5]);
    assert_eq!(stored(res!(sink.post(&["sid-2"], &body("devX", &[(1, "ev broken", &broken)]), T0 + 60_000))), 1);

    let n = names(&s.dir());
    assert!(n.iter().any(|f| f.contains(".ndjson.2025")), "the run must have rotated at least once: {:?}", n);
    let bytes = res!(all_bytes(&s.dir()));
    for p in plants.iter().chain([PHRASE, "abandon"].iter()) {
        assert!(!has(&bytes, p), "{:?} reached the disk", p);
    }
    // Not vacuous: the rows are there, with the markers and the innocent fields.
    assert!(has(&bytes, "ann") && has(&bytes, "kept") && has(&bytes, "tokenStats"));
    assert!(has(&bytes, &fingerprint(PHRASE, 6)) || has(&bytes, "[redacted"), "markers are expected");
    assert!(has(&bytes, &fingerprint(plants[0], 6)), "the passphrase's fingerprint is expected");

    // The control: the same fields written without the sink do carry the plants, so a pass above
    // is the redactor's doing and not a search that cannot see.
    let raw = res!(Row::new(dev, 0, "b1", T0, "state")
        .with("auth", omap(vec![("passphrase", st(plants[0]))]))
        .with("durable_blob", st(plants[2]))
        .with("console", st(&fmt!("boot {} done", PHRASE)))
        .entry(4096)).line(dev, T0);
    for p in [plants[0], plants[2], PHRASE] {
        assert!(has(raw.as_bytes(), p), "the control line should hold {:?}: {}", p, raw);
    }
    Ok(())
}


// The stock string test ==================================================================

// One credential of each shape `fe2o3_text::secret` knows, in two pieces joined at run time, so
// that the scanners that read this file find nothing in it to refuse.
const SHAPED: &[(&str, &str)] = &[
    ("fw",          "_3ZjKq81mAbCdEfGhIjKlMnOpQrSt"),
    ("sk-ant",      "-api03-AbCdEfGhIjKlMnOpQrStUvWx"),
    ("sk-proj",     "-AbCdEfGhIjKlMnOpQrStUvWxYz01"),
    ("sk-or",       "-v1-0123456789abcdef0123456789abcdef"),
    ("sk-",         "AbCdEfGhIjKlMnOpQrStUvWxYz0123456789"),
    ("AKIA",        "IOSFODNN7EXAMPLE"),
    ("ghp",         "_AbCdEfGhIjKlMnOpQrStUvWxYz0123456789"),
    ("github_pat",  "_11ABCDEFG0AbCdEfGhIjKlMnOpQrStUvWxYz0123456789"),
    ("xoxb",        "-1234567890-abcdefghij"),
    ("sk_live",     "_AbCdEfGhIjKlMnOpQrStUv"),
    ("AIza",        "SyA0123456789abcdefghijklmnopqrstuv"),
    ("-----BEGIN ", "OPENSSH PRIVATE KEY-----"),
];

fn cred(i: usize) -> String {
    fmt!("{}{}", SHAPED[i].0, SHAPED[i].1)
}

#[test]
fn shapes_cover_each_credential_shape_whole_and_leave_prose_alone() -> Outcome<()> {
    // Head 0, so that no character of a credential stands in its own fingerprint.
    let red = Redact::new().with_head(0).with_test(Shapes);
    for i in 0..SHAPED.len() {
        let c = cred(i);
        let doc = omap(vec![
            ("alone", st(&c)),
            ("note",  st(&fmt!("deployed with {} this morning", c))),
            ("list",  Dat::List(vec![st("fine"), st(&fmt!("k={}\n", c))])),
            ("deep",  omap(vec![("x", omap(vec![("y", st(&fmt!("a\nb {} c\nd", c)))]))])),
        ]);
        let out = red.dat(&doc);
        let json = res!(compact(&out));
        assert!(!json.contains(&c), "{:?} survived the redactor: {}", SHAPED[i].0, json);
        for p in ["alone", "note", "deep.x.y"] {
            assert!(text_at(&out, p).starts_with("[redacted"), "{} for {:?}: {:?}", p, SHAPED[i].0, text_at(&out, p));
        }
        assert!(json.contains("fine"), "the innocent list member stays: {}", json);
    }
    // An assigned literal under a secret-looking name is a shape too.
    let lit = fmt!("password = \"{}{}\"", "9f3Bq7", "ZmR4tYuIoPkLjHgFdS");
    assert!(Shapes.hit(&lit));
    for ok in [
        "the quick brown fox", "sk-nope", "skip-tracing and key lore", "AKIA", "fw_short",
        "an api_key = \"\" field", "key = \"your-key-here\"", "", "ghp_tooshort",
    ] {
        assert!(!Shapes.hit(ok), "{:?} is not a credential", ok);
    }
    Ok(())
}

#[test]
fn a_marker_and_a_nul_do_not_excuse_a_credential_in_a_feed() -> Outcome<()> {
    let k = cred(0);
    // `scan` is a file reader and takes the author's word; the control shows it does.
    let excused = [
        fmt!("{} # {}", k, secret::MARKER),
        fmt!("{}\n{}", secret::MARKER, k),
        fmt!("\0{}", k),
    ];
    for t in &excused {
        assert!(secret::scan(t.as_bytes()).is_empty(), "scan should excuse {:?}", t);
        assert!(secret::holds(t), "holds must not excuse {:?}", t);
        assert!(Shapes.hit(t), "Shapes must not excuse {:?}", t);
    }
    // And the same through both doors of a sink: nothing of the key reaches a byte.
    let s = Scratch::new("holds");
    let sink = Sink::new(s.dir(), Gates::default())
        .with_redact(Redact::new().with_head(0).with_test(Shapes));
    let row = Row::new("peer", 1, "b", T0, "console")
        .with("line", st(&excused[0]))
        .with("other", st(&excused[2]));
    assert_eq!(res!(sink.write(&["sid"], "peer", &[row], T0)), 1);
    let ev = fmt!("{{\"v\":1,\"d\":\"x\",\"n\":1,\"b\":\"b\",\"t\":1,\"line\":\"{}\"}}", excused[0]);
    let b = body("devX", &[(1, "ev console", &ev), (2, "diag", &excused[1])]);
    assert_eq!(stored(res!(sink.post(&["sid2"], &b, T0 + 5_000))), 2);
    let bytes = res!(all_bytes(&s.dir()));
    assert!(!has(&bytes, &k), "the key reached the disk");
    assert!(has(&bytes, "[redacted"), "markers are expected");
    Ok(())
}

#[test]
fn secret_name_agrees_with_the_regex_engine_on_every_ascii_name() -> Outcome<()> {
    // The hand matcher stands for the JavaScript, whose `\b` and `/i` are ASCII-only. On ASCII
    // names the crate's own engine, which follows the `regex` crate, must say the same.
    let re = res!(Regex::new(
        r"(?i)(?:^|[_.-])(?:apikey|api_key|key|token|secret|passphrase|password|salt|wrapped|wrappedpriv|sealed|seal|privatekey|priv|mnemonic|seed|masterkey)(?:$|[_.-]|enc\b)"));
    let table = res!(fs::read_to_string(
        Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/lens_secret_re.tsv")));
    let mut n = 0;
    for line in table.lines() {
        let name = line.split('\t').next().unwrap_or("");
        if !name.is_ascii() {
            continue;
        }
        assert_eq!(secret_name(name), res!(re.is_match(name)), "on {:?}", name);
        n += 1;
    }
    assert!(n > 2_500, "only {} ASCII names were compared", n);
    Ok(())
}


// The content scrubber ===================================================================

// `tests/data/lens_scrub.tsv` holds each input of the JavaScript scrubber as a recipe and never as a
// credential, so that nothing paste-able is in the repository. `{{n:seed:alphabet}}` is n
// characters: the state starts at `seed * 2654435761` mod 2^32, each character steps it by
// `h * 1103515245 + 12345` in u32 wrapping arithmetic and takes `alphabet[(h >> 16) mod len]`.
// `{{dash5}}` is five hyphens.

fn alphabet(name: &str) -> &'static str {
    match name {
        "alnum"     => "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789",
        "hex"       => "0123456789abcdef",
        "b64"       => "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_",
        "b64std"    => "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789/+",
        "upper36"   => "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789",
        "digit"     => "0123456789",
        other       => panic!("no alphabet {:?}", other),
    }
}

/// `n` characters of one alphabet, from one seed.
fn run(n: usize, seed: u32, alpha: &str) -> String {
    let a: Vec<char> = alphabet(alpha).chars().collect();
    let mut h = (seed as u64 * 2_654_435_761u64) as u32;
    let mut s = String::new();
    for _ in 0..n {
        h = h.wrapping_mul(1_103_515_245).wrapping_add(12_345);
        s.push(a[((h >> 16) as usize) % a.len()]);
    }
    s
}

/// A template of the table, with its recipes expanded.
fn expand(t: &str) -> Outcome<String> {
    let mut out = String::new();
    let mut rest = t;
    while let Some(i) = rest.find("{{") {
        out.push_str(&rest[..i]);
        let tail = &rest[i + 2..];
        let j = res!(tail.find("}}").ok_or_else(|| err!("An unclosed recipe in {:?}.", t; Invalid, Input)));
        let body = &tail[..j];
        if body == "dash5" {
            out.push_str("-----");
        } else {
            let p: Vec<&str> = body.split(':').collect();
            if p.len() != 3 {
                return Err(err!("The recipe {:?} is not n:seed:alphabet.", body; Invalid, Input));
            }
            out.push_str(&run(res!(p[0].parse::<usize>()), res!(p[1].parse::<u32>()), p[2]));
        }
        rest = &tail[j + 2..];
    }
    out.push_str(rest);
    Ok(out)
}

struct Case {
    template:   String,
    input:      String,     // the template, expanded
    want:       String,     // what the JavaScript made of it
    id:         bool,       // scrubbed as a correlation id, so with no entropy catch
}

fn scrub_cases() -> Outcome<Vec<Case>> {
    let table = res!(fs::read_to_string(
        Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/lens_scrub.tsv")));
    let mut cases = Vec::new();
    for line in table.lines() {
        let cols: Vec<&str> = line.split('\t').collect();
        assert_eq!(cols.len(), 3, "bad oracle line {:?}", line);
        let template = text_of(&res!(Dat::decode_json_strict(cols[0], &DecodeLimits::default())));
        let want = text_of(&res!(Dat::decode_json_strict(cols[1], &DecodeLimits::default())));
        let input = res!(expand(&template));
        cases.push(Case { template, input, want, id: cols[2] == "1" });
    }
    Ok(cases)
}

#[test]
fn the_expander_gives_the_pinned_vectors() -> Outcome<()> {
    // The port is held to the JavaScript's before it is trusted with the table.
    for (t, want) in [
        ("{{8:1:hex}}",     "8388dbc2"),
        ("{{12:7:alnum}}",  "Dn8QmkIRy6vU"),
        ("{{10:3:digit}}",  "0086285001"),
        ("{{6:5:upper36}}", "PJMEIR"),
        ("a{{dash5}}b",     "a-----b"),
    ] {
        assert_eq!(res!(expand(t)), want, "{}", t);
    }
    Ok(())
}

#[test]
fn shapes_scrub_the_javascripts_table_to_the_same_text() -> Outcome<()> {
    let cases = res!(scrub_cases());
    assert_eq!(cases.len(), 130, "the table has changed size");
    let mut changed = 0;
    for c in &cases {
        let got = Shapes.scrub(&c.input, c.id);
        assert_eq!(got, c.want, "recipe {:?}", c.template);
        // A second pass finds nothing in the markers of the first.
        assert_eq!(Shapes.scrub(&got, c.id), got, "not idempotent, recipe {:?}", c.template);
        if got != c.input {
            changed += 1;
        }
    }
    let unchanged = cases.len() - changed;
    assert!(changed >= 100 && unchanged >= 20,
        "a table that is nearly one answer proves little: {} changed, {} not", changed, unchanged);
    // Every shape, every pair and the entropy catch is exercised.
    for kind in [
        "pem", "gh", "ghpat", "stripe", "whsec", "sk", "aws", "gcp", "slack", "jwt", "tune",
        "bearer", "urlarg", "named", "awssec", "hi",
    ] {
        let tag = fmt!("[redacted {} #", kind);
        assert!(cases.iter().any(|c| c.want.contains(&tag)), "no case yields {:?}", kind);
    }
    Ok(())
}

#[test]
fn a_hit_is_a_string_the_scrubber_would_change() -> Outcome<()> {
    for c in res!(scrub_cases()) {
        let changed = c.want != c.input;
        let hit = if c.id { Shapes.hit_id(&c.input) } else { Shapes.hit(&c.input) };
        assert_eq!(hit, changed, "recipe {:?}", c.template);
        // What the scrubber wrote is not a hit, so a row the client already scrubbed passes the
        // redactor with its own bytes.
        let again = if c.id { Shapes.hit_id(&c.want) } else { Shapes.hit(&c.want) };
        assert!(!again, "the output of recipe {:?} is itself a hit", c.template);
        let red = Redact::new().with_test(Shapes);
        let (out, covered) = red.walk(&omap(vec![(if c.id { "callId" } else { "msg" }, st(&c.want))]));
        assert!(!covered, "recipe {:?} was covered a second time: {:?}", c.template, out);
    }
    Ok(())
}

#[test]
fn the_shapes_the_commit_hook_does_not_know_are_caught_and_its_scan_is_unchanged() -> Outcome<()> {
    // Each is Daimond's and not the hook's, built from recipes so that no literal is in this file.
    let jwt = fmt!("eyJ{}.{}.{}", run(8, 301, "b64"), run(12, 302, "b64"), run(6, 303, "b64"));
    let cases = [
        ("a JWT",                   jwt),
        ("a webhook secret",        fmt!("whsec_{}", run(20, 304, "alnum"))),
        ("a test-mode Stripe key",  fmt!("sk_test_{}", run(14, 305, "alnum"))),
        ("a test-mode restricted",  fmt!("rk_test_{}", run(14, 306, "alnum"))),
        ("a relay key",             fmt!("tune-{}", run(32, 307, "hex"))),
        ("a temporary AWS id",      fmt!("ASIA{}", run(14, 308, "upper36"))),
        ("a role AWS id",           fmt!("AROA{}", run(14, 309, "upper36"))),
        ("a short GitHub run",      fmt!("ghp_{}", run(16, 310, "alnum"))),
        ("a new Slack token",       fmt!("xoxe-{}", run(14, 311, "alnum"))),
        ("a short Google key",      fmt!("AIza{}", run(32, 312, "b64"))),
        ("an `sk-` key of 16",      fmt!("sk-{}", run(16, 313, "b64"))),
        ("a bearer header",         fmt!("Authorization: Bearer {}", run(20, 314, "b64"))),
        ("a URL's token",           fmt!("https://h.example/cb?token={}&z=1", run(12, 315, "alnum"))),
        ("a named secret",          fmt!("config password: {}", run(12, 316, "alnum"))),
        ("an unnamed blob",         fmt!("blob {} end", run(40, 317, "b64"))),
    ];
    for (what, text) in &cases {
        assert!(secret::scan(text.as_bytes()).is_empty(), "the hook would now refuse {}: {:?}", what, text);
        assert!(!secret::holds(text), "holds, which is the hook's shapes, now sees {}", what);
        assert!(Shapes.hit(text), "Shapes misses {}: {:?}", what, text);
        assert_ne!(Shapes.scrub(text, false), *text, "scrub misses {}", what);
        let out = Redact::new().with_head(0).with_test(Shapes).dat(&omap(vec![("msg", st(text))]));
        assert!(text_at(&out, "msg").starts_with("[redacted"), "{}: {:?}", what, text_at(&out, "msg"));
    }
    Ok(())
}

#[test]
fn a_placeholder_under_a_secret_name_is_scrubbed_as_daimond_scrubs_it() -> Outcome<()> {
    // The hook excuses a placeholder, being noisy over source; Daimond's scrubber does not, being
    // over a feed, and `Shapes` is no weaker than it.
    let t = "password: \"your-key-here\"";
    assert!(secret::scan(t.as_bytes()).is_empty() && !secret::holds(t));
    assert!(Shapes.hit(t));
    assert!(Shapes.scrub(t, false).starts_with("password: \"[redacted named #"));
    Ok(())
}

#[test]
fn a_correlation_id_is_excused_from_the_entropy_catch_and_nothing_else() -> Outcome<()> {
    let blob = run(40, 401, "b64");
    let key = fmt!("sk-{}", run(20, 402, "b64"));
    let doc = omap(vec![
        ("callId",  st(&blob)),
        ("note",    st(&blob)),
        ("id",      st(&key)),
        ("sid",     st(&blob)),
        ("inner",   omap(vec![("turn", st(&blob)), ("x", st(&blob))])),
    ]);
    let red = Redact::new().with_test(Shapes);
    let out = red.dat(&doc);
    assert_eq!(text_at(&out, "callId"), blob, "Daimond's own id fields keep their values");
    assert!(text_at(&out, "note").starts_with("[redacted"), "any other field is held to the catch");
    assert!(text_at(&out, "id").starts_with("[redacted"), "an id holding a key is still a key");
    assert!(text_at(&out, "sid").starts_with("[redacted"), "sid is the application's to name");
    assert_eq!(text_at(&out, "inner.turn"), blob, "at any depth");
    assert!(text_at(&out, "inner.x").starts_with("[redacted"), "an id does not excuse its neighbour");
    // The application names its own, and a list under an id field is ids as well.
    let red = Redact::new().with_test(Shapes).id_key("sid");
    let out = red.dat(&omap(vec![
        ("sid",     st(&blob)),
        ("turn",    Dat::List(vec![st(&blob), st(&blob)])),
        ("other",   Dat::List(vec![st(&blob)])),
    ]));
    assert_eq!(text_at(&out, "sid"), blob);
    let j = res!(compact(&out));
    assert_eq!(j.matches(&blob).count(), 3, "two list members under turn, and sid: {}", j);
    assert!(j.contains("[redacted"), "the list under another name is still covered: {}", j);
    // A row meets the same rule through its payload's field names.
    let row = Row::new("peer", 1, "b", T0, "console").with("callId", st(&blob)).with("msg", st(&blob));
    let out = red.row(&row);
    let get = |n: &str| out.body.iter().find(|(k, _)| k == n).map(|(_, v)| text_of(v)).unwrap_or_default();
    assert_eq!(get("callId"), blob);
    assert!(get("msg").starts_with("[redacted"), "{:?}", get("msg"));
    // And a caller's own test is not excused for an id: the default is the same answer.
    let own = Redact::new().with_test(|s: &str| s.contains("zzz"));
    let out = own.dat(&omap(vec![("callId", st("a zzz b"))]));
    assert!(text_at(&out, "callId").starts_with("[redacted"));
    Ok(())
}


// The tap on a websocket's messages ======================================================

#[cfg(feature = "async")]
mod tap {
    use super::*;

    use oxedyne_fe2o3_iop_db::api::NoDatabase;
    use oxedyne_fe2o3_net::{
        lens::{
            Dir,
            Frame,
            Tap,
        },
        ws::{
            encode_message,
            handler::WebSocketEchoHandler,
            read_message,
            tap::{
                encode_message_tapped,
                read_message_tapped,
                FrameTap,
                NoTap,
            },
            WebSocket,
            WebSocketLimits,
            WebSocketMessage,
        },
    };

    use std::sync::Arc;

    use tokio::io::{
        duplex,
        AsyncWriteExt,
    };

    const CHUNK: usize = 1_024;

    /// What a connection knows about itself, which is what a filter gets to see.
    struct Conn {
        sid:    String,
        dev:    String,
    }

    fn conn(sid: &str) -> Conn {
        Conn { sid: sid.to_string(), dev: "peer".to_string() }
    }

    /// The safe filter: every frame, reduced to its kind and its size.
    fn shape_only(_dir: Dir, c: &Conn, msg: &WebSocketMessage) -> Option<Frame> {
        Some(Frame::new(&[&c.sid], &c.dev).shape(msg))
    }

    fn num_at(d: &Dat, path: &str) -> Option<u64> {
        match at(d, path)? {
            Dat::U8(n)  => Some(*n as u64),
            Dat::U16(n) => Some(*n as u64),
            Dat::U32(n) => Some(*n as u64),
            Dat::U64(n) => Some(*n),
            Dat::I8(n)  => u64::try_from(*n).ok(),
            Dat::I16(n) => u64::try_from(*n).ok(),
            Dat::I32(n) => u64::try_from(*n).ok(),
            Dat::I64(n) => u64::try_from(*n).ok(),
            _           => None,
        }
    }

    /// The events a key holds, each the JSON a row carried in its `data`.
    fn events<T: StrTest>(sink: &Sink<T>, key: &[&str]) -> Outcome<Vec<Dat>> {
        let mut out = Vec::new();
        for l in res!(lines(&sink.path(key))) {
            out.push(res!(Dat::decode_json_strict(&text_at(&l, "data"), &DecodeLimits::default())));
        }
        Ok(out)
    }

    fn text(s: &str) -> WebSocketMessage { WebSocketMessage::Text(s.to_string()) }

    /// Frames a message as a client would, masked.
    fn from_client(m: &WebSocketMessage) -> Outcome<Vec<u8>> {
        encode_message(m, true, CHUNK, CHUNK)
    }

    /// One tapped read.
    async fn read_one<X: FrameTap>(bytes: &[u8], tap: &X, ctx: &X::Ctx) -> Outcome<Option<WebSocketMessage>> {
        let mut stream = bytes;
        let mut buf = Vec::new();
        read_message_tapped(&mut stream, &mut buf, CHUNK, WebSocketLimits::default(), tap, ctx).await
    }

    #[tokio::test]
    async fn frames_in_both_directions_reach_the_sink_as_kind_and_size_only() -> Outcome<()> {
        let s = Scratch::new("tap-both");
        let sink = Arc::new(Sink::new(s.dir(), Gates::default()));
        let tap = Tap::new(sink.clone(), "b9", shape_only);
        let c = conn("sess-1");

        // In: a text frame, then a binary one, then a ping.
        let secret_text = "do-not-keep-this-chat-line";
        let got = res!(read_one(&res!(from_client(&text(secret_text))), &tap, &c).await);
        assert!(matches!(got, Some(WebSocketMessage::Text(ref t)) if t == secret_text));
        let got = res!(read_one(&res!(from_client(&WebSocketMessage::Binary(vec![7u8; 300]))), &tap, &c).await);
        assert!(matches!(got, Some(WebSocketMessage::Binary(ref b)) if b.len() == 300));
        res!(read_one(&res!(from_client(&WebSocketMessage::Ping(vec![1, 2, 3]))), &tap, &c).await);

        // Out: a text reply and a close, framed unmasked as a server does.
        let out = res!(encode_message_tapped(&text("pong!"), false, CHUNK, CHUNK, &tap, &c));
        assert_eq!(out, res!(encode_message(&text("pong!"), false, CHUNK, CHUNK)));
        res!(encode_message_tapped(&WebSocketMessage::Close(None, Some("bye".to_string())), false, CHUNK, CHUNK, &tap, &c));

        let ev = res!(events(&sink, &["sess-1"]));
        assert_eq!(ev.len(), 5, "{:?}", ev);
        let want = [
            ("frame.in", "text",   secret_text.len() as u64),
            ("frame.in", "binary", 300),
            ("frame.in", "ping",   3),
            ("frame.out", "text",  5),
            ("frame.out", "close", 3),
        ];
        for (i, (kind, op, bytes)) in want.iter().enumerate() {
            let e = &ev[i];
            assert_eq!(num_at(e, "n"), Some(i as u64 + 1), "n counts from 1, as Daimond's does: {:?}", e);
            assert_eq!(text_at(e, "d"), "peer");
            assert_eq!(text_at(e, "b"), "b9");
            assert_eq!(text_at(e, "op"), *op, "{:?}", e);
            assert_eq!(num_at(e, "bytes"), Some(*bytes), "{:?}", e);
            // The tag carries the direction.
            let tag = text_at(&res!(lines(&sink.path(&["sess-1"])))[i], "tag");
            assert_eq!(tag, fmt!("ev {}", kind));
        }
        // The default arm never carried content.
        let bytes = res!(all_bytes(&s.dir()));
        assert!(!has(&bytes, secret_text), "a frame's text reached the file");
        assert_eq!(tap.lost(), 0);
        Ok(())
    }

    #[tokio::test]
    async fn the_filters_reduction_is_what_lands_and_a_forgetful_filter_meets_the_redactor() -> Outcome<()> {
        let s = Scratch::new("tap-reduce");
        let sink = Arc::new(Sink::new(s.dir(), Gates::default())
            .with_redact(Redact::new().with_head(0)));
        // Oxegen's case: an enrol bundle carries a biometric, and only its shape may be kept.
        let filter = |dir: Dir, c: &Conn, msg: &WebSocketMessage| -> Option<Frame> {
            let t = match msg {
                WebSocketMessage::Text(t)   => t,
                _                           => return Some(Frame::new(&[&c.sid], &c.dev).shape(msg)),
            };
            let d = match Dat::decode_json_strict(t, &DecodeLimits::default()) {
                Ok(d)   => d,
                Err(_)  => return None,
            };
            let kind = text_at(&d, "kind");
            if kind == "EnrolBundle" {
                return Some(Frame::new(&[&c.sid], &c.dev)
                    .with("kind", st(&kind))
                    .with("bundle", st(&text_at(&d, "bundle")))
                    .with("item", st(&text_at(&d, "item")))
                    .with("bytes", Dat::U64(t.len() as u64))
                    .with("dir", st(if dir == Dir::In { "in" } else { "out" })));
            }
            if kind == "Forgetful" {
                // A filter that keeps a field it should not: the sink's redactor still covers it.
                return Some(Frame::new(&[&c.sid], &c.dev).with("token", st(&text_at(&d, "token"))));
            }
            None
        };
        let tap = Tap::new(sink.clone(), "b9", filter);
        let c = conn("sess-2");
        let raw = "RAW-FACE-TEMPLATE-0123456789";
        let enrol = fmt!("{{\"kind\":\"EnrolBundle\",\"bundle\":\"b-7\",\"item\":\"face-3\",\"blob\":\"{}\"}}", raw);
        res!(read_one(&res!(from_client(&text(&enrol))), &tap, &c).await);
        res!(encode_message_tapped(&text(&enrol), false, CHUNK, CHUNK, &tap, &c));
        let leaky = "PLANT-token-from-a-filter";
        let forgot = fmt!("{{\"kind\":\"Forgetful\",\"token\":\"{}\"}}", leaky);
        res!(read_one(&res!(from_client(&text(&forgot))), &tap, &c).await);

        let ev = res!(events(&sink, &["sess-2"]));
        assert_eq!(ev.len(), 3, "{:?}", ev);
        for (i, dir) in ["in", "out"].iter().enumerate() {
            assert_eq!(text_at(&ev[i], "kind"), "EnrolBundle");
            assert_eq!(text_at(&ev[i], "bundle"), "b-7");
            assert_eq!(text_at(&ev[i], "item"), "face-3");
            assert_eq!(num_at(&ev[i], "bytes"), Some(enrol.len() as u64));
            assert_eq!(text_at(&ev[i], "dir"), *dir);
        }
        assert!(text_at(&ev[2], "token").starts_with("[redacted"), "{:?}", ev[2]);
        let bytes = res!(all_bytes(&s.dir()));
        assert!(!has(&bytes, raw), "the raw payload reached a file");
        assert!(!has(&bytes, leaky), "a forgetful filter leaked past the sink's redactor");
        assert!(has(&bytes, "face-3"), "the reduction is there");
        Ok(())
    }

    #[tokio::test]
    async fn none_drops_a_frame_and_leaves_no_gap_in_the_sequence() -> Outcome<()> {
        let s = Scratch::new("tap-none");
        let sink = Arc::new(Sink::new(s.dir(), Gates::default()));
        // Keeps the text frames only.
        let tap = Tap::new(sink.clone(), "b", |_d: Dir, c: &Conn, m: &WebSocketMessage| match m {
            WebSocketMessage::Text(_)   => Some(Frame::new(&[&c.sid], &c.dev).shape(m)),
            _                           => None,
        });
        let c = conn("sess-3");
        for m in [text("a"), WebSocketMessage::Binary(vec![0]), text("bb"), WebSocketMessage::Ping(vec![]), text("ccc")] {
            res!(read_one(&res!(from_client(&m)), &tap, &c).await);
        }
        let ev = res!(events(&sink, &["sess-3"]));
        let ns: Vec<Option<u64>> = ev.iter().map(|e| num_at(e, "n")).collect();
        assert_eq!(ns, vec![Some(1), Some(2), Some(3)], "{:?}", ev);
        let sizes: Vec<Option<u64>> = ev.iter().map(|e| num_at(e, "bytes")).collect();
        assert_eq!(sizes, vec![Some(1), Some(2), Some(3)]);
        Ok(())
    }

    #[tokio::test]
    async fn a_sink_that_cannot_write_counts_the_loss_and_the_frame_still_flows() -> Outcome<()> {
        let s = Scratch::new("tap-lost");
        res!(fs::create_dir_all(&s.0));
        // A regular file where the directory must go.
        let blocker = s.0.join("blocker");
        res!(fs::write(&blocker, b"x"));
        let sink = Arc::new(Sink::new(blocker.join("lens"), Gates::default()));
        let tap = Tap::new(sink.clone(), "b", shape_only);
        let c = conn("sess-4");
        for want in ["one", "two", "three"] {
            let got = res!(read_one(&res!(from_client(&text(want))), &tap, &c).await);
            assert!(matches!(got, Some(WebSocketMessage::Text(ref t)) if t == want), "the frame must flow: {:?}", got);
        }
        let out = res!(encode_message_tapped(&text("x"), false, CHUNK, CHUNK, &tap, &c));
        assert!(!out.is_empty());
        assert_eq!(tap.lost(), 4, "each write that failed is counted");
        Ok(())
    }

    type Echo<'a, S, X> = WebSocket<'a, 8, u64, (), (), NoDatabase<8, u64, (), ()>, S, WebSocketEchoHandler, X>;

    #[tokio::test]
    async fn a_websocket_taps_its_own_read_and_send() -> Outcome<()> {
        let s = Scratch::new("tap-ws");
        let sink = Arc::new(Sink::new(s.dir(), Gates::default()));
        let tap = Tap::new(sink.clone(), "b", shape_only);
        let (mut server_end, mut client_end) = duplex(8_192);
        let mut ws = Echo::new_server(&mut server_end, WebSocketEchoHandler, CHUNK, CHUNK)
            .with_tap(&tap, conn("sess-5"));
        res!(client_end.write_all(&res!(from_client(&text("hello")))).await);
        let got = res!(ws.read().await);
        assert!(matches!(got, Some(WebSocketMessage::Text(ref t)) if t == "hello"));
        res!(ws.send(&text("hello back")).await);
        // The peer hears the same bytes the tap saw framed.
        let mut buf = Vec::new();
        let heard = res!(read_message(&mut client_end, &mut buf, CHUNK, WebSocketLimits::default()).await);
        assert!(matches!(heard, Some(WebSocketMessage::Text(ref t)) if t == "hello back"));
        let ev = res!(events(&sink, &["sess-5"]));
        assert_eq!(ev.len(), 2, "{:?}", ev);
        assert_eq!((text_at(&ev[0], "op"), num_at(&ev[0], "bytes")), ("text".to_string(), Some(5)));
        assert_eq!((text_at(&ev[1], "op"), num_at(&ev[1], "bytes")), ("text".to_string(), Some(10)));
        let tags: Vec<String> = res!(lines(&sink.path(&["sess-5"]))).iter().map(|l| text_at(l, "tag")).collect();
        assert_eq!(tags, vec!["ev frame.in".to_string(), "ev frame.out".to_string()]);
        Ok(())
    }

    #[tokio::test]
    async fn a_websocket_with_no_tap_compiles_unchanged_and_behaves() -> Outcome<()> {
        let (mut server_end, mut client_end) = duplex(8_192);
        // The eight-argument spelling, as `fe2o3_steel` writes it, still names a complete type.
        let mut ws: WebSocket<'_, 8, u64, (), (), NoDatabase<8, u64, (), ()>, _, WebSocketEchoHandler> =
            WebSocket::new_server(&mut server_end, WebSocketEchoHandler, CHUNK, CHUNK);
        res!(client_end.write_all(&res!(from_client(&text("plain")))).await);
        let got = res!(ws.read().await);
        assert!(matches!(got, Some(WebSocketMessage::Text(ref t)) if t == "plain"));
        res!(ws.send(&text("plain back")).await);
        let mut buf = Vec::new();
        let heard = res!(read_message(&mut client_end, &mut buf, CHUNK, WebSocketLimits::default()).await);
        assert!(matches!(heard, Some(WebSocketMessage::Text(ref t)) if t == "plain back"));
        Ok(())
    }

    // Zero cost with no tap is shown by type, not by counting allocations: a counting global
    // allocator needs `unsafe`, which this tree forbids. `NoTap` and its context occupy no bytes,
    // its hooks are empty and inlined, and the tapped free functions give what the untapped ones
    // give, byte for byte.
    #[tokio::test]
    async fn no_tap_costs_nothing_and_changes_nothing() -> Outcome<()> {
        assert_eq!(std::mem::size_of::<NoTap>(), 0);
        assert_eq!(std::mem::size_of::<<NoTap as FrameTap>::Ctx>(), 0);
        for m in [text("same"), WebSocketMessage::Binary(vec![9u8; 2_000]), WebSocketMessage::Ping(vec![1])] {
            // Unmasked, so the framing is deterministic.
            let plain = res!(encode_message(&m, false, 512, 512));
            let tapped = res!(encode_message_tapped(&m, false, 512, 512, &NoTap, &()));
            assert_eq!(plain, tapped);
            let mut a: &[u8] = &plain;
            let mut b: &[u8] = &plain;
            let (mut ba, mut bb) = (Vec::new(), Vec::new());
            let x = res!(read_message(&mut a, &mut ba, 512, WebSocketLimits::default()).await);
            let y = res!(read_message_tapped(&mut b, &mut bb, 512, WebSocketLimits::default(), &NoTap, &()).await);
            assert_eq!(fmt!("{:?}", x), fmt!("{:?}", y));
            assert_eq!(a.len(), b.len(), "both consumed the same bytes");
        }
        // The same holds for a tap behind a reference or an `Arc`.
        let s = Scratch::new("tap-arc");
        let sink = Arc::new(Sink::new(s.dir(), Gates::default()));
        let tap = Arc::new(Tap::new(sink.clone(), "b", shape_only));
        let c = conn("sess-6");
        res!(read_one(&res!(from_client(&text("via arc"))), &tap, &c).await);
        assert_eq!(res!(events(&sink, &["sess-6"])).len(), 1);
        Ok(())
    }

    #[test]
    fn a_direction_names_its_kind() {
        assert_eq!(Dir::In.kind(), "frame.in");
        assert_eq!(Dir::Out.kind(), "frame.out");
    }
}

/// A device label is a string a client sends like any other: one that holds a credential is covered
/// before it is written beside each line, by the post and by a caller's own write.
#[test]
fn a_device_label_that_holds_a_credential_is_covered() -> Outcome<()> {
    let s = Scratch::new("devsecret");
    let sink = Sink::new(s.dir(), Gates::default()).with_redact(Redact::new().with_head(0).with_test(Shapes));
    // Assembled here and not written down, so the source holds no credential for a hook to find.
    let key = fmt!("{}{}{}", "sk_", "live_", "Qm9xZ3RwYWJjZGVmZ2hpamtsbW5v");
    assert_eq!(stored(res!(sink.post(&["k"], &body(&key, &[(1, "a", "x")]), T0))), 1);
    let rows = vec![Row::new("src", 1, "b", T0, "note")];
    res!(sink.write(&["w"], &key, &rows, T0 + 5_000));
    for name in ["k", "w"] {
        let text = res!(fs::read_to_string(sink.path(&[name])), IO, File, Read);
        assert!(!text.contains(&key), "the label is covered in {}: {}", name, text);
        assert!(text.contains("[redacted"), "and says it was covered in {}: {}", name, text);
    }
    // An ordinary label is left alone.
    assert_eq!(stored(res!(sink.post(&["plain"], &body("devABC", &[(1, "a", "x")]), T0))), 1);
    let text = res!(fs::read_to_string(sink.path(&["plain"])), IO, File, Read);
    assert!(text.contains("\"device\":\"devABC\""), "{}", text);
    Ok(())
}


// The word-run test ======================================================================

struct PhraseCase {
    text:   String,
    n:      usize,
    hit:    bool,
    spans:  Vec<String>,
}

fn json_text(col: &str) -> Outcome<String> {
    Ok(text_of(&res!(Dat::decode_json_strict(col, &DecodeLimits::default()))))
}

/// `tests/data/lens_phrase.tsv`: the list, then each case as input, n, hit and the spans found. The
/// JavaScript's `createRunGuard` is held to the same file (`lens/js/test/phrase.test.mjs`).
fn phrase_table() -> Outcome<(Vec<String>, Vec<PhraseCase>)> {
    let table = res!(fs::read_to_string(
        Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/lens_phrase.tsv")));
    let mut list = Vec::new();
    let mut cases = Vec::new();
    for line in table.lines() {
        if let Some(rest) = line.strip_prefix("#list\t") {
            list = rest.split(' ').map(|w| w.to_string()).collect();
            continue;
        }
        let cols: Vec<&str> = line.split('\t').collect();
        assert_eq!(cols.len(), 4, "bad case line {:?}", line);
        let spans = match res!(Dat::decode_json_strict(cols[3], &DecodeLimits::default())) {
            Dat::List(l)    => l.iter().map(text_of).collect(),
            other           => panic!("spans are a list, not {:?}", other),
        };
        cases.push(PhraseCase {
            text:   res!(json_text(cols[0])),
            n:      res!(cols[1].parse::<usize>()),
            hit:    cols[2] == "1",
            spans,
        });
    }
    Ok((list, cases))
}

#[test]
fn a_word_run_agrees_with_the_shared_case_file() -> Outcome<()> {
    let (list, cases) = res!(phrase_table());
    assert_eq!(cases.len(), 40, "the table has changed size");
    assert!(list.iter().any(|w| w.contains('-')), "the list holds hyphenated entries");
    let (mut hits, mut misses) = (0, 0);
    for c in &cases {
        let p = Phrase::new(list.iter().map(|w| w.as_str()), c.n);
        let got: Vec<String> = p.spans(&c.text).iter().map(|&(a, b)| c.text[a..b].to_string()).collect();
        assert_eq!(got, c.spans, "spans of {:?} at n={}", c.text, c.n);
        assert_eq!(p.has(&c.text), c.hit, "has {:?} at n={}", c.text, c.n);
        assert_eq!(p.hit(&c.text), c.hit);
        assert_eq!(p.hit_id(&c.text), c.hit, "an id is held to the same test");
        if c.hit { hits += 1 } else { misses += 1 }
    }
    assert!(hits >= 20 && misses >= 10, "a table that is nearly one answer proves little: {} hits, {} misses", hits, misses);
    Ok(())
}

// What the peer's test did before this one: a word is a run of letters, and nothing else joins them.
fn split_only(list: &[String], n: usize, s: &str) -> bool {
    let mut run = 0;
    for tok in s.split(|c: char| !c.is_ascii_alphabetic()) {
        if tok.is_empty() {
            continue;
        }
        if list.iter().any(|w| w == &tok.to_ascii_lowercase()) {
            run += 1;
            if run >= n {
                return true;
            }
        } else {
            run = 0;
        }
    }
    false
}

#[test]
fn splitting_on_every_non_letter_misses_a_passphrase_with_a_hyphenated_word() -> Outcome<()> {
    // The control for the case file: the split-only test agrees with it everywhere except where a
    // hyphenated list entry is spelled, which is the hole the entry rule closes.
    let (list, cases) = res!(phrase_table());
    let mut missed = Vec::new();
    for c in &cases {
        if split_only(&list, c.n, &c.text) != c.hit {
            missed.push(c.text.clone());
        }
    }
    assert!(missed.len() >= 5, "the hyphenated entries are in the table: {:?}", missed);
    for m in &missed {
        assert!(["drop-down", "t-shirt", "yo-yo", "felt-tip", "Drop-Down", "T-SHIRT"].iter().any(|e| m.contains(e)),
            "the only disagreement is a hyphenated entry: {:?}", m);
    }
    Ok(())
}

#[test]
fn one_test_can_stand_for_two() {
    let w = Phrase::new(["alpha", "beta"], 2);
    let either = Or(Shapes, w);
    assert!(either.hit("alpha beta"));
    assert!(either.hit(&fmt!("{}{}", "sk-ant", "-api03-AbCdEfGhIjKlMnOpQrStUvWx")));
    assert!(!either.hit("alpha gamma beta"));
    assert!(either.hit_id(&fmt!("{}{}", "sk-ant", "-api03-AbCdEfGhIjKlMnOpQrStUvWx")), "an id is still held to a shape");
}


// Chunk rows =============================================================================

// The eight words that the tests below plant, and the stock string test with them added.
fn chunk_test() -> Or<Shapes, Phrase> {
    Or(Shapes, Phrase::new(PHRASE.split(' '), 8))
}

fn chunk_sink(s: &Scratch) -> Sink<Or<Shapes, Phrase>> {
    Sink::new(s.dir(), Gates { min_interval_ms: 0, ..Gates::default() })
        .with_redact(Redact::new().with_head(0).with_test(chunk_test()))
}

// A snapshot as the page makes it: scrubbed JSON, plain prose in its free fields. The filler is
// there to make a few chunks of it.
fn snapshot_json(note: &str) -> String {
    fmt!(
        "{{\"ts\":1790000000000,\"iso\":\"2026-10-03T08:00:00.000Z\",\"sid\":\"k3j9x0a1qz\",\"device\":\"p4m8w2zr\",\
\"build\":\"387d393\",\"why\":\"screen\",\"vis\":\"visible\",\"w\":390,\"screen\":\"oxegen_home\",\
\"app\":{{\"phase\":\"home\",\"busy\":false,\"lang\":\"en\"}},\"member\":{{\"known\":true,\"fp\":\"[redacted …#1f3a9c/44]\"}},\
\"wallet\":{{\"coins\":3,\"epoch\":19}},\"net\":{{\"state\":\"live\",\"wire\":\"ws\",\"may_count\":true}},\
\"ls\":{{\"keys\":9}},\"idb\":{{\"dbs\":1}},\"lens\":{{\"depth\":4,\"health\":\"ok\",\"fault\":false}},\
\"note\":\"{}\",\"more\":\"the page sat on the home screen while the member read the notice and the net stayed live\"}}",
        note)
}

fn rows_of(kind: &str, id: &str, enc: &str, size: usize, wrap: bool) -> Vec<(i64, String, String)> {
    let parts: Vec<String> = enc.as_bytes().chunks(size).map(|c| String::from_utf8_lossy(c).into_owned()).collect();
    let n = parts.len();
    parts.into_iter().enumerate().map(|(i, p)| {
        let data = if wrap {
            // Words of sixteen, as MIME wraps base64.
            p.as_bytes().chunks(16).map(|w| String::from_utf8_lossy(w).into_owned()).collect::<Vec<String>>().join(" ")
        } else {
            p
        };
        (T0 as i64 + i as i64, fmt!("ds {} {} {}/{}", kind, id, i + 1, n), data)
    }).collect()
}

fn post_rows(sink: &Sink<Or<Shapes, Phrase>>, key: &str, rows: &[(i64, String, String)], at: u64) -> Outcome<usize> {
    let borrowed: Vec<(i64, &str, &str)> = rows.iter().map(|(t, g, d)| (*t, g.as_str(), d.as_str())).collect();
    Ok(stored(res!(sink.post(&[key], &body("dev", &borrowed), at))))
}

// The (tag, data) of each line a key has stored, in order.
fn kept(sink: &Sink<Or<Shapes, Phrase>>, key: &str) -> Outcome<Vec<(String, String)>> {
    let mut out = Vec::new();
    for l in res!(lines(&sink.path(&[key]))) {
        out.push((text_at(&l, "tag"), text_at(&l, "data")));
    }
    Ok(out)
}

fn marked(data: &str) -> bool { data.starts_with("[redacted") }

#[test]
fn a_base64_snapshot_chunk_is_kept_intact() -> Outcome<()> {
    let json = snapshot_json("a quiet moment");
    assert!(!chunk_test().hit(&json), "the plain text is innocent, which is what the test is about");
    let url = base64::encode_url(json.as_bytes());
    let std = base64::encode(json.as_bytes());
    let s = Scratch::new("chunk-intact");
    let sink = chunk_sink(&s);
    // The page's form, Daimond's, and the first Oxegen pages' (words of sixteen).
    let forms = [
        ("url",     rows_of("snapshot", "s1-1", &url, 288, false)),
        ("std",     rows_of("telemetry", "t1", &std, 360, false)),
        ("words",   rows_of("snapshot", "s1-2", &url, 288, true)),
    ];
    for (k, (key, rows)) in forms.iter().enumerate() {
        assert!(rows.len() >= 3, "{}: a few chunks", key);
        assert_eq!(res!(post_rows(&sink, key, rows, T0 + 10_000 * k as u64)), rows.len());
        let got = res!(kept(&sink, key));
        assert_eq!(got.len(), rows.len());
        for ((tag, data), (_, want_tag, want)) in got.iter().zip(rows.iter()) {
            assert_eq!(tag, want_tag);
            assert_eq!(data, want, "{}: a chunk of a clean bundle is stored as it came", key);
        }
        // And what was kept reads back to the bundle.
        let whole: String = got.iter().map(|(_, d)| d.replace(' ', "")).collect();
        let back = if *key == "std" { res!(base64::decode(&whole)) } else { res!(base64::decode_url(&whole)) };
        assert_eq!(String::from_utf8_lossy(&back), json, "{}", key);
    }
    Ok(())
}

#[test]
fn a_chunk_whose_decoded_text_holds_eight_words_is_covered() -> Outcome<()> {
    let json = snapshot_json(&fmt!("the member typed {} by mistake", PHRASE));
    let url = base64::encode_url(json.as_bytes());
    let s = Scratch::new("chunk-phrase");
    let sink = chunk_sink(&s);
    let rows = rows_of("snapshot", "s2-1", &url, 288, false);
    assert!(rows.len() >= 3);
    assert_eq!(res!(post_rows(&sink, "k", &rows, T0)), rows.len());
    let got = res!(kept(&sink, "k"));
    assert_eq!(got.len(), rows.len());
    // The bundle is one: a hit anywhere covers every chunk of it, so a reader finds it broken.
    for (i, (tag, data)) in got.iter().enumerate() {
        assert_eq!(tag, &rows[i].1);
        assert!(marked(data), "chunk {} is covered: {}", i + 1, data);
        assert!(!data.contains(&rows[i].2[..16]), "and holds none of the chunk");
    }
    let bytes = res!(all_bytes(&s.dir()));
    assert!(!has(&bytes, "abandon") && !has(&bytes, &url[..40]));
    Ok(())
}

#[test]
fn a_chunk_whose_decoded_text_holds_a_key_is_covered() -> Outcome<()> {
    let key = cred(1);
    let json = snapshot_json(&fmt!("config says {}", key));
    let s = Scratch::new("chunk-key");
    let sink = chunk_sink(&s);
    for (k, (_, (kind, enc, size))) in [
        ("url", ("snapshot", base64::encode_url(json.as_bytes()), 288)),
        ("std", ("telemetry", base64::encode(json.as_bytes()), 360)),
    ].into_iter().enumerate() {
        let rows = rows_of(kind, "s3", &enc, size, false);
        assert_eq!(res!(post_rows(&sink, &fmt!("k{}", k), &rows, T0 + 10_000 * k as u64)), rows.len());
        for (tag, data) in res!(kept(&sink, &fmt!("k{}", k))) {
            assert!(marked(&data), "{}: {}", tag, data);
        }
    }
    let bytes = res!(all_bytes(&s.dir()));
    assert!(!has(&bytes, &key) && !has(&bytes, &key[..12]));
    Ok(())
}

#[test]
fn a_secret_that_straddles_a_cut_is_seen_and_every_chunk_is_covered() -> Outcome<()> {
    // The eight words stand across the page's cut at 288 characters (216 bytes), five in the first
    // chunk and three in the second.
    let json = fmt!("{{\"p\":\"{}typed {} in the box\",\"rest\":{}}}",
        "plain words ".repeat(15), PHRASE, snapshot_json("x"));
    let a = json.find(PHRASE).unwrap_or(0);
    assert!(a < 216 && 216 < a + PHRASE.len(), "the cut falls inside the words: {}", a);
    let url = base64::encode_url(json.as_bytes());
    let rows = rows_of("snapshot", "s4", &url, 288, false);
    assert!(rows.len() >= 2);
    // Alone, no chunk holds the eight words: the cut has halved them.
    let red = Redact::new().with_head(0).with_test(chunk_test());
    for (_, tag, data) in &rows {
        let one = vec![(tag.clone(), data.clone())];
        assert_eq!(judge(&red, 400, &one), vec![Verdict::Clean], "{} alone is innocent", tag);
    }
    let s = Scratch::new("chunk-straddle");
    let sink = chunk_sink(&s);
    assert_eq!(res!(post_rows(&sink, "fwd", &rows, T0)), rows.len());
    for (tag, data) in res!(kept(&sink, "fwd")) {
        assert!(marked(&data), "{}: {}", tag, data);
    }
    // The order of the rows in the post makes no difference.
    let mut rev = rows.clone();
    rev.reverse();
    assert_eq!(res!(post_rows(&sink, "rev", &rev, T0 + 10_000)), rev.len());
    for (tag, data) in res!(kept(&sink, "rev")) {
        assert!(marked(&data), "{}: {}", tag, data);
    }
    Ok(())
}

#[test]
fn a_payload_that_is_not_the_base64_of_text_is_no_chunk_at_all() -> Outcome<()> {
    let s = Scratch::new("chunk-fake");
    let sink = chunk_sink(&s);
    // Bytes that are not text: an image, say, sent under a snapshot's tag.
    let bin: Vec<u8> = (0..300u32).map(|i| (i.wrapping_mul(2_654_435_761) >> 13) as u8 | 0x80).collect();
    let image = base64::encode_url(&bin);
    assert!(chunk::text(&image).is_none(), "the bytes are not text");
    let key = cred(1);
    let rows: Vec<(i64, String, String)> = vec![
        (1, "ds snapshot f1 1/4".to_string(), PHRASE.to_string()),
        (2, "ds snapshot f1 2/4".to_string(), key.clone()),
        (3, "ds snapshot f1 3/4".to_string(), image[..288].to_string()),
        (4, "ds snapshot f1 4/4".to_string(), fmt!("{}", PHRASE.to_uppercase())),
    ];
    assert_eq!(res!(post_rows(&sink, "k", &rows, T0)), 4);
    for (tag, data) in res!(kept(&sink, "k")) {
        assert!(marked(&data), "{} is guarded as any row is: {}", tag, data);
    }
    let bytes = res!(all_bytes(&s.dir()));
    assert!(!has(&bytes, "abandon") && !has(&bytes, "ABANDON") && !has(&bytes, &key) && !has(&bytes, &image[..40]));
    Ok(())
}

#[test]
fn only_an_exact_chunk_tag_is_a_chunk() -> Outcome<()> {
    let ok = ChunkTag::parse("ds snapshot s1-7 2/5");
    assert_eq!(ok, Some(ChunkTag { kind: "snapshot".to_string(), id: "s1-7".to_string(), i: 2, n: 5 }));
    assert_eq!(ChunkTag::parse("ds telemetry t9 1/1").map(|t| (t.kind, t.i, t.n)), Some(("telemetry".to_string(), 1, 1)));
    let bad = [
        "ds snapshot s 0/3", "ds snapshot s 4/3", "ds snapshots s 1/3", "ds snapshot s 1/3 extra", "DS snapshot s 1/3",
        "ds  snapshot s 1/3", "ds snapshot  s 1/3", "ds snapshot s 1/", "ds snapshot s /3", "ds snapshot s a/3",
        "ds snapshot s +1/3", "ds snapshot s 1/3 ", " ds snapshot s 1/3", "ds snapshot s", "ds snapshot 1/3", "ds s 1/3",
        "ev snapshot s 1/3", "ds snapshot s 1/3/4", "ds snapshot s 1/99999999999", "", "ds",
    ];
    for t in bad {
        assert_eq!(ChunkTag::parse(t), None, "{:?} is not a chunk's tag", t);
    }
    // Their payloads get no exemption: the same real base64 is covered under each of them.
    let enc = base64::encode_url(snapshot_json("x").as_bytes());
    let s = Scratch::new("chunk-tags");
    let sink = chunk_sink(&s);
    let rows: Vec<(i64, String, String)> = bad.iter().enumerate()
        .filter(|(_, t)| !t.is_empty())
        .map(|(i, t)| (i as i64 + 1, t.to_string(), enc[..288].to_string()))
        .collect();
    assert_eq!(res!(post_rows(&sink, "k", &rows, T0)), rows.len());
    for (tag, data) in res!(kept(&sink, "k")) {
        assert!(marked(&data), "{:?} is no chunk, and is guarded as a row: {}", tag, data);
    }
    // While the exact tag is let through.
    let good = vec![(1i64, "ds snapshot s 2/5".to_string(), enc[..288].to_string())];
    assert_eq!(res!(post_rows(&sink, "good", &good, T0 + 10_000)), 1);
    assert_eq!(res!(kept(&sink, "good")), vec![("ds snapshot s 2/5".to_string(), enc[..288].to_string())]);
    Ok(())
}

#[test]
fn a_row_that_is_not_a_chunk_is_guarded_exactly_as_before() -> Outcome<()> {
    let enc = base64::encode_url(snapshot_json("x").as_bytes());
    let s = Scratch::new("chunk-plain");
    let sink = chunk_sink(&s);
    let rows = vec![
        (1i64, "diag".to_string(), enc[..288].to_string()),
        (2, "ds-snapshot s 1/3".to_string(), enc[..288].to_string()),
        (3, "diag".to_string(), "an ordinary line of log text".to_string()),
    ];
    assert_eq!(res!(post_rows(&sink, "k", &rows, T0)), 3);
    let got = res!(kept(&sink, "k"));
    assert!(marked(&got[0].1) && marked(&got[1].1), "long random-looking runs are covered: {:?}", got);
    assert_eq!(got[2].1, "an ordinary line of log text");
    Ok(())
}

#[test]
fn a_cut_off_a_quantum_still_reads_as_a_run_and_fails_closed_alone() -> Outcome<()> {
    let json = snapshot_json("a quiet moment");
    let url = base64::encode_url(json.as_bytes());
    let rows = rows_of("snapshot", "s5", &url, 290, false);
    assert!(rows.len() >= 3);
    // 290 characters is not a whole number of quanta, so no chunk but the first decodes alone.
    assert!(chunk::text(&rows[1].2).is_none(), "the second chunk starts inside a quantum");
    let s = Scratch::new("chunk-cut");
    let sink = chunk_sink(&s);
    // Together they are the bundle, and the bundle is innocent.
    assert_eq!(res!(post_rows(&sink, "run", &rows, T0)), rows.len());
    for (i, (tag, data)) in res!(kept(&sink, "run")).iter().enumerate() {
        assert_eq!(data, &rows[i].2, "{}", tag);
    }
    // One of them posted alone is not provably text, so it meets the whole guard and is covered.
    assert_eq!(res!(post_rows(&sink, "alone", &rows[1..2], T0 + 10_000)), 1);
    assert!(marked(&res!(kept(&sink, "alone"))[0].1));
    Ok(())
}

#[test]
fn the_text_of_a_payload_allows_a_partial_character_at_each_end_and_nothing_else() {
    let s = "h\u{e9}llo w\u{f6}rld \u{2603} snowman and a longer tail to be cut at the end \u{2603}";
    let b = s.as_bytes();
    // Starting inside the first \u{e9}: one stray continuation byte.
    let lead = &b[2..];
    assert!(std::str::from_utf8(lead).is_err());
    assert!(chunk::text(&base64::encode_url(lead)).is_some(), "a cut inside a character at the start");
    // Ending inside the last \u{2603}: an unfinished character.
    let tail = &b[..b.len() - 1];
    assert!(std::str::from_utf8(tail).is_err());
    assert!(chunk::text(&base64::encode_url(tail)).is_some(), "a cut inside a character at the end");
    assert!(chunk::text(&base64::encode_url(b)).is_some());
    // Bytes that are not text anywhere else are not text.
    let mut bad = b.to_vec();
    bad[10] = 0xff;
    assert!(chunk::text(&base64::encode_url(&bad)).is_none());
    // Padded, unpadded, white space; the two alphabets mixed are neither.
    assert_eq!(chunk::text(&base64::encode(b"foobar!")).as_deref(), Some("foobar!"));
    assert_eq!(chunk::text(&base64::encode_url(b"foobar!")).as_deref(), Some("foobar!"));
    assert_eq!(chunk::text("Zm9v YmFy\nIQ").as_deref(), Some("foobar!"));
    assert_eq!(chunk::text(""), Some(String::new()));
    assert!(chunk::text("ab+/cd-_").is_none(), "both alphabets at once");
    assert!(chunk::text("Zm9vYmFy!").is_none(), "a stray character");
    assert!(chunk::text("Zm9vY").is_none(), "a lone character over a quantum");
    // Plain words with their spaces taken out decode to bytes that are not text.
    assert!(chunk::text(PHRASE).is_none());
}


// A bundle that parses as JSON meets the whole redactor (F5, 2026-10-04) ================

// A snapshot with one more member in it, which is raw JSON.
fn snapshot_with(member: &str) -> String {
    let base = snapshot_json("x");
    fmt!("{},{}}}", &base[..base.len() - 1], member)
}

// The eight words of PHRASE spread over a structure's strings in four shapes. The raw text of the
// first two is one run, and the letter-only keys and the keys `t` of the last two break it.
fn spread(shape: usize) -> String {
    let w: Vec<&str> = PHRASE.split(' ').collect();
    let join = |v: Vec<String>| v.join(",");
    match shape {
        0 => fmt!("[{}]", join(w.iter().map(|x| fmt!("\"{}\"", x)).collect())),
        1 => fmt!("{{{}}}", join(w.iter().enumerate().map(|(i, x)| fmt!("\"{}\":\"{}\"", i, x)).collect())),
        2 => fmt!("{{{}}}", join(w.iter().enumerate().map(|(i, x)| fmt!("\"{}\":\"{}\"", (b'a' + i as u8) as char, x)).collect())),
        _ => fmt!("[{}]", join(w.iter().map(|x| fmt!("{{\"t\":\"{}\"}}", x)).collect())),
    }
}

// What a key has stored as a reader reads it: the data of each row joined, decoded as it was sent.
fn reread(got: &[(String, String)], std: bool) -> Outcome<String> {
    let whole: String = got.iter().map(|(_, d)| d.replace(' ', "")).collect();
    let bytes = if std { res!(base64::decode(&whole)) } else { res!(base64::decode_url(&whole)) };
    Ok(String::from_utf8_lossy(&bytes).into_owned())
}

fn parsed(text: &str) -> Outcome<Dat> {
    Ok(res!(Dat::decode_json_strict(text, &DecodeLimits::default())))
}

#[test]
fn words_spread_over_a_bundles_strings_are_covered_whatever_stands_between_them() -> Outcome<()> {
    let names = ["list", "digits", "letters", "objects"];
    let s = Scratch::new("chunk-spread");
    let sink = chunk_sink(&s);
    for (k, name) in names.iter().enumerate() {
        let json = snapshot_with(&fmt!("\"spread\":{}", spread(k)));
        let rows = rows_of("snapshot", &fmt!("sp-{}", name), &base64::encode_url(json.as_bytes()), 288, false);
        assert!(rows.len() >= 3, "{}: a few chunks", name);
        assert_eq!(res!(post_rows(&sink, name, &rows, T0 + 10_000 * k as u64)), rows.len());
        let got = res!(kept(&sink, name));
        assert_eq!(got.len(), rows.len(), "{}: a row for a row", name);
        for ((tag, _), (_, want, _)) in got.iter().zip(rows.iter()) {
            assert_eq!(tag, want, "{}: the tags stand", name);
        }
        let whole = got.iter().all(|(_, d)| marked(d));
        assert_eq!(whole, k < 2, "{}: the raw text met the run in the first two shapes alone", name);
        if whole {
            assert!(!has(&res!(all_bytes(&s.dir())), &rows[0].2[..40]), "{}: no chunk is stored as it came", name);
            continue;
        }
        // The raw text never met the run, so the bundle is covered in place, and is still a bundle.
        let text = res!(reread(&got, false));
        for w in PHRASE.split(' ') {
            assert!(!text.contains(w), "{}: the word {:?} is stored", name, w);
        }
        let back = res!(parsed(&text));
        assert_eq!(text_at(&back, "screen"), "oxegen_home", "{}: the rest of it is kept", name);
        assert_eq!(text_at(&back, "app.phase"), "home", "{}", name);
        let leaves = fmt!("{:?}", at(&back, "spread"));
        assert!(leaves.contains("[redacted"), "{}: the strings of the run are fingerprints: {}", name, leaves);
    }
    Ok(())
}

#[test]
fn seven_words_spread_over_a_bundle_are_a_bundle_as_it_came() -> Outcome<()> {
    let seven: Vec<String> = PHRASE.split(' ').take(7).map(|x| fmt!("{{\"t\":\"{}\"}}", x)).collect();
    let json = snapshot_with(&fmt!("\"spread\":[{}]", seven.join(",")));
    let rows = rows_of("snapshot", "sv", &base64::encode_url(json.as_bytes()), 288, false);
    let s = Scratch::new("chunk-seven");
    let sink = chunk_sink(&s);
    assert_eq!(res!(post_rows(&sink, "k", &rows, T0)), rows.len());
    for ((_, data), (_, _, want)) in res!(kept(&sink, "k")).iter().zip(rows.iter()) {
        assert_eq!(data, want, "an innocent bundle is stored as it came");
    }
    Ok(())
}

#[test]
fn a_secret_named_field_inside_a_bundle_is_covered_in_place() -> Outcome<()> {
    let json = snapshot_with("\"passphrase\":\"hunter2\",\"auth\":{\"seed\":\"s33d\",\"user\":\"ann\"}");
    assert!(!chunk_test().hit(&json), "the string test alone finds nothing here, which is the point");
    let s = Scratch::new("chunk-named");
    let sink = chunk_sink(&s);
    let forms = [
        ("url",     "snapshot",     base64::encode_url(json.as_bytes()),    288, false, false),
        ("std",     "telemetry",    base64::encode(json.as_bytes()),        360, false, true),
        ("words",   "snapshot",     base64::encode_url(json.as_bytes()),    288, true,  false),
    ];
    for (k, (key, kind, enc, size, wrap, std)) in forms.iter().enumerate() {
        let rows = rows_of(kind, &fmt!("nm-{}", key), enc, *size, *wrap);
        assert!(rows.len() >= 3, "{}: a few chunks", key);
        assert_eq!(res!(post_rows(&sink, key, &rows, T0 + 10_000 * k as u64)), rows.len());
        let got = res!(kept(&sink, key));
        assert_eq!(got.len(), rows.len(), "{}: a row for a row", key);
        for ((tag, data), (_, want, _)) in got.iter().zip(rows.iter()) {
            assert_eq!(tag, want, "{}", key);
            assert!(data.len() <= Gates::default().max_data, "{}: a row within the gate", key);
        }
        // It reads back, in the alphabet it was sent in, as the bundle with two values covered.
        let back = res!(parsed(&res!(reread(&got, *std))));
        assert_eq!(text_at(&back, "passphrase"), fingerprint("hunter2", 0), "{}", key);
        assert_eq!(text_at(&back, "auth.seed"), fingerprint("s33d", 0), "{}", key);
        assert_eq!(text_at(&back, "auth.user"), "ann", "{}: only the secrets go", key);
        assert_eq!(text_at(&back, "screen"), "oxegen_home", "{}", key);
    }
    let bytes = res!(all_bytes(&s.dir()));
    assert!(!has(&bytes, "hunter2") && !has(&bytes, "s33d"));
    Ok(())
}

#[test]
fn a_bundle_too_big_to_hold_its_covering_is_covered_whole() -> Outcome<()> {
    // Each short value becomes a longer fingerprint, so the covered text outgrows the rows it came in.
    let members: Vec<String> = (0..60).map(|i| fmt!("\"a_key_{}\":\"{}\"", i, i % 10)).collect();
    let json = snapshot_with(&members.join(","));
    let rows = rows_of("snapshot", "big", &base64::encode_url(json.as_bytes()), 288, false);
    let s = Scratch::new("chunk-big");
    let sink = chunk_sink(&s);
    assert_eq!(res!(post_rows(&sink, "k", &rows, T0)), rows.len());
    let got = res!(kept(&sink, "k"));
    assert_eq!(got.len(), rows.len());
    for (tag, data) in &got {
        assert!(marked(data), "{} is covered whole, since the covering does not fit: {}", tag, data);
    }
    Ok(())
}

#[test]
fn a_run_that_is_not_the_whole_bundle_is_covered_whole_if_it_needs_covering() -> Outcome<()> {
    // One chunk of a set that claims two: whatever the other holds, this one cannot be re-cut.
    let json = "{\"passphrase\":\"hunter2\"}";
    let s = Scratch::new("chunk-half");
    let sink = chunk_sink(&s);
    let rows = vec![(1i64, "ds snapshot h1 1/2".to_string(), base64::encode_url(json.as_bytes()))];
    assert_eq!(res!(post_rows(&sink, "half", &rows, T0)), 1);
    assert!(marked(&res!(kept(&sink, "half"))[0].1));
    // The same text as the whole of a set of one is covered in place.
    let one = vec![(1i64, "ds snapshot h2 1/1".to_string(), base64::encode_url(json.as_bytes()))];
    assert_eq!(res!(post_rows(&sink, "whole", &one, T0 + 10_000)), 1);
    let got = res!(kept(&sink, "whole"));
    assert!(!marked(&got[0].1));
    let back = res!(parsed(&res!(reread(&got, false))));
    assert_eq!(text_at(&back, "passphrase"), fingerprint("hunter2", 0));
    Ok(())
}

#[test]
fn a_test_says_which_of_a_structures_strings_it_reads_only_together() {
    let text = "red\ngreen\nblue";
    let p = Phrase::new(["red", "green", "blue"], 3);
    assert_eq!(p.joined_spans(text), vec![(0, text.len())], "a word run is read across the strings");
    assert!(Shapes.joined_spans(text).is_empty(), "a shape is read in one string");
    assert!((|s: &str| s.contains("red")).joined_spans(text).is_empty(), "so is a closure's test");
    assert_eq!(Or(Shapes, p).joined_spans(text), vec![(0, text.len())], "and `Or` asks both");
}

#[test]
fn a_covering_that_shrinks_a_bundle_still_gives_a_row_for_a_row() -> Outcome<()> {
    // A long value that no shape finds, under a name that is a secret's, becomes a short fingerprint.
    let long = "w ".repeat(400);
    let json = snapshot_with(&fmt!("\"passphrase\":\"{}\"", long));
    assert!(!chunk_test().hit(&json));
    let rows = rows_of("snapshot", "sh", &base64::encode_url(json.as_bytes()), 288, false);
    let s = Scratch::new("chunk-shrink");
    let sink = chunk_sink(&s);
    assert_eq!(res!(post_rows(&sink, "k", &rows, T0)), rows.len());
    let got = res!(kept(&sink, "k"));
    assert_eq!(got.len(), rows.len(), "a row for a row, whatever it holds");
    for ((tag, _), (_, want, _)) in got.iter().zip(rows.iter()) {
        assert_eq!(tag, want);
    }
    let (before, after): (usize, usize) = (rows.iter().map(|r| r.2.len()).sum(), got.iter().map(|r| r.1.len()).sum());
    assert!(after + 400 < before, "the bundle is shorter for the covering: {} then {}", before, after);
    let back = res!(parsed(&res!(reread(&got, false))));
    assert_eq!(text_at(&back, "passphrase"), fingerprint(&long, 0));
    assert_eq!(text_at(&back, "screen"), "oxegen_home");
    Ok(())
}
